export const typeDefs = "# 燕云百业工具 v2 GraphQL Schema\n# 按页面组织，非对象导向\n# 当期 = version 字段匹配当前版本（如 intl-v2.3），无 isCurrent 布尔值\n# 实体命名：Grouping（组队），非 Car\n\n# ============ 枚举 ============\n\nenum GroupingTab {\n  ACTIVITY  # 双十人本\n  TALENT    # 天赋组队\n  RACE      # 竞速报名\n  TOWER     # 爬塔\n}\n\nenum GroupingType {\n  ACTIVITY\n  TALENT\n  RACE\n  TOWER\n}\n\nenum DexTab {\n  MECHANICS  # 机制\n  TALENTS    # 天赋\n  SHOUTS     # 喊话\n}\n\n# ============ 通用类型 ============\n\ntype Seat {\n  index: Int!\n  nickname: String\n  weapon: String  # 流派，如 破竹·樽\n  role: String    # 输出 / 奶（服务端按流派推导）\n  uid: String\n  occupied: Boolean!\n  ready: Boolean!  # 就位标记 (发车提醒用): 落座成员已确认就位\n  mine: Boolean!   # 本座是否为当前观看者本人的座位 (身份戳比对, 服务端判定)\n}\n\ntype Dungeon {\n  id: ID!\n  name: String!\n  sealText: String!     # 印章短字 (个别副本有专属二字, 其余取规范名前二字; 后端按规范名计算, 与 locale 无关)\n  version: String!      # 如 intl-v2.3\n  playerCount: Int!     # 10人 / 5人\n  size: Int!            # 同 playerCount (D1 dungeons.size), 供发车表单按副本定人数\n  season: String        # 赛季码 S1..S5 (后端 dex 迁移写入, 未分类为 null)\n  seasonName: String    # 赛季展示名 (后端赛季表: S1 出鞘之刃 / S2 Rewind / S3 Seek Within / S4 Forge Ahead / S5 Ever Aflame)\n  category: String      # 游戏内分类 (试锋 / 梦洄 / 鉴心 / 铸矩 / 传薪), 与赛季等级档一一对应\n  level: Int            # 副本等级档 (51/56/61/66/71/81/86/91/96/100)\n  bosses: [Boss!]!\n}\n\ntype Boss {\n  id: ID!\n  name: String!\n  dungeon: Dungeon!\n  mechanics: [Mechanic!]!  # 结构化机制\n  talents: [Talent!]!      # 1-x / 2-x 天赋\n  shouts: [Shout!]!        # 喊话宏\n}\n\ntype Mechanic {\n  phase: String!        # 如 \"P1\", \"P2\", \"P3\"\n  title: String!\n  description: String!  # 中文\n}\n\ntype Talent {\n  code: String!         # 如 \"1-1\", \"2-3\"\n  description: String!  # 中文，视频确认标注\n  verified: Boolean!    # 是否视频确认\n}\n\ntype Shout {\n  text: String!         # 喊话内容\n  copyable: Boolean!\n}\n\n# ============ 页面：百业集结 Hub ============\n# URL: /\n\ntype Query {\n  hubPage: HubPage!\n}\n\ntype HubPage {\n  guilds: [GuildCard!]!\n}\n\n# ============ 页面：法律页 (服务条款 / 隐私政策) ============\n# URL: /terms 与 /privacy — 公开页面, 匿名可达 (登录页页脚入口)。\n# 正文由 LegalPageShell 的 gen 方法按 locale 从后端文案目录生成\n# (zh-CN 源文 + en 全译, 其余语言逐字段回退源文), 前端不打包正文。\n\nenum LegalKind {\n  TERMS\n  PRIVACY\n}\n\nextend type Query {\n  legalPage(kind: LegalKind!): LegalPage!\n}\n\ntype LegalPage {\n  kind: LegalKind!\n  title: String!\n  updatedText: String!\n  backLabel: String!\n  sections: [LegalSection!]!\n}\n\ntype LegalSection {\n  heading: String!\n  body: String!\n}\n\ntype GuildCard {\n  slug: String!\n  name: String!\n  slogan: String\n  gameVersion: String!\n  memberCount: Int!\n  avatarUrl: String\n}\n\n# ============ 页面：公会主页 ============\n# URL: /{slug}\n\nextend type Query {\n  guildPage(slug: String!): GuildPage!\n  targetedNudgePreview(slug: String!, eventId: Int!, segmentKind: String!, segmentValue: String): TargetedNudgePreviewResult!\n  myContribution(slug: String!): MyContributionResult!\n}\n\ntype GuildPage {\n  slug: String!\n  name: String!\n  gameVersion: String!\n  currentVersion: String!\n  tabs: [String!]!  # [\"双十人本\", \"天赋组队\", \"竞速报名\", \"攻略\", \"流派攻略\"]\n}\n\n# ============ 移动端 Bloks-lite: 带类型积木对象 ============\n# 内容区不是 JSON blob: 每个积木是一个带类型的 GraphQL object, 容器带\n# children, 前端以 Relay fragment 递归渲染直到叶子 (basic element)。\n# 服务端组合什么对象就是权限与分发决定本身: 车头的树里才有解散按钮\n# 对象, 本人座位才有离队动作对象, 客户端零权限分支。\n\n# Relay server 3D (@module) 协议标量: js 字段的返回值是不透明引用,\n# 服务端把 module 参数原样回传, 客户端据此经 operationLoader /\n# MatchContainer loader 解析出拆分操作与渲染组件。\nscalar JSDependency\n\ninterface Block {\n  children: [Block!]!\n  # server 3D: 每个具体积木经此字段回传 @module 选中的组件/操作引用。\n  js(module: String!, id: String): JSDependency\n}\n\n# 容器积木: 分区 (可选标题 + 子积木), 递归在此继续\ntype SectionBlock implements Block {\n  title: String\n  children: [Block!]!\n  js(module: String!, id: String): JSDependency\n}\n\ntype SectionHeaderBlock implements Block {\n  text: String!\n  children: [Block!]!\n  js(module: String!, id: String): JSDependency\n}\n\ntype TextBlock implements Block {\n  text: String!\n  variant: String! # title | meta | muted | body\n  children: [Block!]!\n  js(module: String!, id: String): JSDependency\n}\n\ntype BannerBlock implements Block {\n  text: String!\n  children: [Block!]!\n  js(module: String!, id: String): JSDependency\n}\n\ntype ChipRowBlock implements Block {\n  chips: [String!]!\n  children: [Block!]!\n  js(module: String!, id: String): JSDependency\n}\n\ntype GroupingCardBlock implements Block {\n  groupingId: ID!\n  title: String!\n  badgeText: String!\n  timeText: String!\n  dungeonName: String\n  peopleText: String!\n  statusText: String!\n  action: Action\n  children: [Block!]!\n  js(module: String!, id: String): JSDependency\n}\n\ntype SeatGridBlock implements Block {\n  seats: [SeatEntry!]!\n  children: [Block!]!\n  js(module: String!, id: String): JSDependency\n}\n\n# 座位条目 (数据叶子, 非积木): 动作对象按观看者在服务端生成\ntype SeatEntry {\n  index: Int!\n  occupied: Boolean!\n  nickname: String\n  weapon: String\n  role: String\n  healer: Boolean!\n  isLeader: Boolean!\n  ready: Boolean!  # 就位标记 (发车提醒用)\n  readyAction: Action  # 就位切换动作: 仅本人座位且车未完成/未出发时下发\n  action: Action\n}\n\ntype ActionButtonBlock implements Block {\n  label: String!\n  style: String! # primary | ghost | danger\n  action: Action\n  children: [Block!]!\n  js(module: String!, id: String): JSDependency\n}\n\ntype EmptyStateBlock implements Block {\n  text: String!\n  children: [Block!]!\n  js(module: String!, id: String): JSDependency\n}\n\ntype SpacerBlock implements Block {\n  size: Int!\n  children: [Block!]!\n  js(module: String!, id: String): JSDependency\n}\n\n# 版本兜底: 客户端 blocksVersion 低于某积木所需版本时, 服务端以此对象\n# 替代下发 (最老的客户端也能把它渲染成一条提示), 绝不下发未知类型。\ntype FallbackBlock implements Block {\n  text: String!\n  children: [Block!]!\n  js(module: String!, id: String): JSDependency\n}\n\n# ---------- 动作 (带类型对象; 客户端按类型映射到已知 mutation/导航) ----------\ninterface Action {\n  actionType: String!\n}\n\ntype NavigateAction implements Action {\n  actionType: String!\n  slug: String!\n  groupingId: ID!\n  name: String!\n  readOnly: Boolean!\n  nick: String!\n}\n\ntype JoinAction implements Action {\n  actionType: String!\n  groupingId: ID!\n  seatIndex: Int!\n}\n\ntype LeaveAction implements Action {\n  actionType: String!\n  groupingId: ID!\n  uid: String!\n  confirmTitle: String!\n  confirmMessage: String!\n  okLabel: String!\n  cancelLabel: String!\n}\n\ntype DisbandAction implements Action {\n  actionType: String!\n  groupingId: ID!\n  confirmTitle: String!\n  confirmMessage: String!\n  okLabel: String!\n  cancelLabel: String!\n}\n\n# 编辑车队动作 (词汇 v3): 只有车头的详情树里才有挂它的按钮对象,\n# 与 DisbandAction 同一条服务端组合规则; 点开后宿主打开编辑表单,\n# 保存走 updateGrouping (服务端再验车头)。\ntype EditAction implements Action {\n  actionType: String!\n  groupingId: ID!\n}\n\n# 完成车队动作 (词汇 v4): 与 DisbandAction 同形 (确认文案走动作对象);\n# 只有车头且车未完成时详情树才下发, 落地走 completeGrouping (服务端再验)。\ntype CompleteAction implements Action {\n  actionType: String!\n  groupingId: ID!\n  confirmTitle: String!\n  confirmMessage: String!\n  okLabel: String!\n  cancelLabel: String!\n}\n\n# 恢复车队动作 (词汇 v4): 撤销完成, 无确认字段 (恢复可逆、低风险);\n# 只有车头且车已完成时详情树才下发, 落地走 reopenGrouping (服务端再验)。\ntype UncompleteAction implements Action {\n  actionType: String!\n  groupingId: ID!\n}\n\n# 就位切换动作: 只有座位本人 (身份戳命中) 且车为 open/closed 时,\n# 随 SeatEntry.readyAction 下发; ready 为点击后要设置的目标状态;\n# 落地走 setSeatReady (服务端按身份戳再验)。\ntype SetReadyAction implements Action {\n  actionType: String!\n  groupingId: ID!\n  ready: Boolean!\n}\n\n# ============ 页面：组队列表 ============\n# URL: /{slug}?tab=activity (嵌入公会主页)\n\nextend type Query {\n  groupingListPage(slug: String!, tab: GroupingTab!): GroupingListPage!\n}\n\ntype GroupingListPage {\n  groupings: [Grouping!]!\n  # 本百业共享模板 (与页签无关, 全百业一份): 建车表单据此渲染模板区\n  # (列表/套用/存当前表单/改删入口); 改删判定在每个模板的 manageActions。\n  groupingTemplates: [GroupingTemplate!]!\n  currentVersion: String!\n  # 移动端 Bloks-lite: 本页内容区积木对象树 (带类型 object, 非 JSON);\n  # blocksVersion = 客户端声明的积木词汇版本, 低于某积木所需版本时服务端\n  # 以 FallbackBlock 替代下发; weekOffset 相对当前周 (周界与全站同口径:\n  # 周一 05:00 北京时间)。组合即权限: 观看者拿到的对象就是他能看的全部。\n  blocks(blocksVersion: Int, weekOffset: Int): [Block!]!\n  # UI 文案: 全部由本页 shell 的 gen 方法按请求 locale 生成 (未选中不生成)\n  tabActivityLabel: String!\n  tabTalentLabel: String!\n  tabRaceLabel: String!\n  tabTowerLabel: String!\n  typeShortActivity: String!\n  typeShortTalent: String!\n  typeShortRace: String!\n  typeShortTower: String!\n  typeShortGather: String!\n  typeShortExplore: String!\n  prevWeekLabel: String!\n  nextWeekLabel: String!\n  weekHeaderTemplate: String!\n  # 按日分组组头 (周框架不变, 一屏内按查看者本地自然日分组):\n  # 模板含 {month}/{day}/{weekday} 占位; weekdayNames 下标 0=周日 (与\n  # JS getDay 对齐), 整表按 locale 生成。移动端的组头由服务端在 Block\n  # 树里拼好整句 (SectionHeaderBlock), 不经这两个字段。\n  dayGroupHeaderTemplate: String!\n  weekdayNames: [String!]!\n  undatedGroupLabel: String!\n  emptyInteractiveText: String!\n  emptyReadonlyText: String!\n  statusOpenLabel: String!\n  peopleTemplate: String!\n  newCarLabel: String!\n  sealText: String!\n  # 发车表单文案 (表单从列表页打开; 详情页 shell 同名同口径)\n  formCreateTitle: String!\n  formEditTitle: String!\n  formTypeLabel: String!\n  formTypeActivityLabel: String!\n  formTypeTalentLabel: String!\n  formTypeRaceLabel: String!\n  formTypeTowerLabel: String!\n  formCapacityTemplate: String!\n  formHintActivity: String!\n  formHintDungeonTemplate: String!\n  formHintTalent: String!\n  formHintRace: String!\n  formHintTower: String!\n  formTitleLabel: String!\n  formTitlePlaceholder: String!\n  formStartsLabel: String!\n  formMonthTemplate: String!\n  formDayTemplate: String!\n  formHourTemplate: String!\n  formMinuteTemplate: String!\n  formDungeonLabel: String!\n  formDungeonNoneLabel: String!\n  formNicknameLabel: String!\n  formNicknamePlaceholder: String!\n  formSectLabel: String!\n  formCancelLabel: String!\n  formSubmitCreateLabel: String!\n  formSubmitEditLabel: String!\n  formSubmittingLabel: String!\n  formToastSect: String!\n  formToastSaved: String!\n  formToastSaveFailedTemplate: String!\n  formToastPosted: String!\n  formToastCreateFailedTemplate: String!\n  formTitleTemplate: String!\n  formCustomFieldsTitle: String!\n  formCustomFieldAddLabel: String!\n  formCustomFieldLabelPlaceholder: String!\n  formCustomFieldTypeText: String!\n  formCustomFieldTypeChoice: String!\n  formCustomFieldOptionsPlaceholder: String!\n  formCustomFieldRequiredLabel: String!\n  formCustomFieldRemoveLabel: String!\n  formCustomFieldEmptyText: String!\n  # 车队模板区文案 (建车表单内): 模板行本身的改删文案在模板的 manageActions 上\n  templateSectionTitle: String!\n  templateNameLabel: String!\n  templateNamePlaceholder: String!\n  templateSaveLabel: String!\n  templateUpdateLabel: String!\n  templateEditingNoticeTemplate: String!\n  templateCancelEditLabel: String!\n  templateEmptyText: String!\n  templateWhenTodayTemplate: String!\n  templateWhenTomorrowTemplate: String!\n  templateWhenDaysTemplate: String!\n  templateToastSaved: String!\n  templateToastSaveFailedTemplate: String!\n  templateToastDeleted: String!\n  templateToastDeleteFailedTemplate: String!\n  templateMetaTemplate: String!\n}\n\n# ============ 自定义报名表字段 (F7) ============\n# 创建者为组队/模板定义的报名字段: 类型是受约束小集 (单行文本 /\n# 单选), 字段数与长度上限由后端校验。label 与 options 是创建者写\n# 的数据, 不是 UI 文案; 答案只对车头与本百业管理员可见。\n\nenum CustomFieldType {\n  TEXT\n  CHOICE\n}\n\ntype CustomField {\n  id: ID!\n  label: String!\n  fieldType: CustomFieldType!\n  options: [String!]!\n  required: Boolean!\n}\n\ninput CustomFieldInput {\n  label: String!\n  fieldType: CustomFieldType!\n  options: [String!]\n  required: Boolean\n}\n\ninput SignupAnswerInput {\n  fieldId: ID!\n  value: String!\n}\n\n# 名册答案行: 仅当观看者可管理本车时由详情页下发 (否则字段为 null)\ntype RosterAnswer {\n  uid: String!\n  nickname: String!\n  fieldId: ID!\n  fieldLabel: String!\n  value: String!\n}\n\n# ============ 车队模板 (百业共享) ============\n# 成员把常用建车配置存为模板, 建车时一键预填表单。模板只存相对发车\n# 偏移 (天数 + 当地时刻), 不存绝对日期; 副本存名称 (与 events.dungeon\n# 同口径), dungeonId 按当前图鉴实时解析, 副本下线时为 null。\n\ntype GroupingTemplate {\n  id: ID!\n  name: String!\n  type: GroupingType!\n  title: String!\n  dungeonName: String\n  dungeonId: ID\n  maxSlots: Int!\n  startDaysAhead: Int!\n  startHour: Int!\n  startMinute: Int!\n  creatorDiscordId: String\n  creatorName: String\n  # 改删动作对象: 仅模板创建者或本百业管理员可见, 否则 null;\n  # mutation 处以同一判定独立复验。\n  manageActions: GroupingTemplateManageActions\n  # 本模板的自定义报名表字段: 发车时随模板带入车的字段定义\n  customFields: [CustomField!]!\n}\n\ntype GroupingTemplateManageActions {\n  editLabel: String!\n  deleteLabel: String!\n  deleteConfirmTitle: String!\n  deleteConfirmMessageTemplate: String!\n}\n\n# 详情页「存为模板」动作对象: 仅可在本百业写的观看者可见。\ntype GroupingTemplateSave {\n  buttonLabel: String!\n  dialogTitle: String!\n  nameLabel: String!\n  submitLabel: String!\n  toastSaved: String!\n  toastFailedTemplate: String!\n}\n\ntype GroupingTemplatePayload {\n  ok: Boolean!\n  template: GroupingTemplate\n  error: String\n  errorCode: String\n}\n\ninput GroupingTemplateInput {\n  name: String!\n  type: GroupingType!\n  title: String!\n  dungeonId: ID\n  startsInDays: Int!\n  startHour: Int!\n  startMinute: Int!\n  customFields: [CustomFieldInput!]\n}\n\ninput CreateGroupingTemplateInput {\n  slug: String!\n  name: String!\n  type: GroupingType!\n  title: String!\n  dungeonId: ID\n  startsInDays: Int!\n  startHour: Int!\n  startMinute: Int!\n  customFields: [CustomFieldInput!]\n}\n\ninput SaveGroupingTemplateInput {\n  groupingId: ID!\n  name: String\n}\n\ntype Grouping {\n  id: ID!\n  title: String!\n  type: GroupingType!\n  startsAt: String!\n  dungeon: Dungeon\n  seats: [Seat!]!\n  occupiedCount: Int!\n  readyCount: Int!  # 已就位人数 (发车提醒就位进度)\n  maxSlots: Int!\n  status: String!  # open / closed / draft / completed (已完成: 不进列表、不发提醒, 详情直达可打开)\n  creatorDiscordId: String  # 车头 (创建者) 的 Discord id; 旧车/REST 车未记录为 null\n  # 本车的自定义报名表字段 (创建者定义; 报名时成员按此填写)\n  customFields: [CustomField!]!\n}\n\n# ============ 页面：组队详情 ============\n# URL: /{slug}/grouping/{id}\n\nextend type Query {\n  groupingDetailPage(slug: String, id: ID!): GroupingDetailPage!\n}\n\ntype GroupingDetailPage {\n  grouping: Grouping!\n  # 分享 URL: 本车的稳定短链 (后端懒铸造, 首次下发时生成、之后恒同);\n  # 客户端分享动作只用这个字符串, 不自拼 URL。\n  shareUrl: String!\n  # 移动端 Bloks-lite: 本页内容区积木对象树 (同 GroupingListPage.blocks);\n  # 逐座动作与解散按钮按观看者在服务端生成, 客户端不重建权限。\n  blocks(blocksVersion: Int): [Block!]!\n  # 管理动作对象: 仅当观看者可管理本车时存在 (车头本人, 或本百业的\n  # 管理员——2026-10-26 裁决与车头同权); 否则为 null, 客户端不渲染\n  # 编辑/完成/恢复/解散入口。服务端在 mutation 处独立复验。\n  manageActions: GroupingManageActions\n  # 盟友共享控件 (P20): 仅当观看者可管理本车时存在 (同 manageActions\n  # 判定); 否则为 null。setGroupingAllySharing 在 mutation 处独立复验。\n  allySharing: AllySharingControl\n  # 存为模板动作对象: 仅当观看者可在本百业写 (建车同权) 时存在, 否则 null;\n  # 客户端据此渲染「存为模板」入口, mutation 处独立复验。\n  templateSave: GroupingTemplateSave\n  # 报名表答案名册: 仅可管理本车的观看者 (车头 / 本百业管理员) 得到\n  # 非空值; 其他观看者为 null, 答案不下发。mutation/查询处同一判定。\n  rosterAnswers: [RosterAnswer!]\n  rosterAnswersTitle: String!\n  # 无管理码，人人可管\n  # UI 文案: 全部由本页 shell 的 gen 方法按请求 locale 生成\n  detailNotFoundText: String!\n  detailBackToListLabel: String!\n  detailShareLabel: String!\n  detailEditLabel: String!\n  detailDisbandLabel: String!\n  detailDisbandingLabel: String!\n  detailStatusOpenLabel: String!\n  detailPeopleTemplate: String!\n  detailOpenHint: String!\n  detailReadonlyHint: String!\n  detailToastDisbanded: String!\n  detailToastDisbandFailedTemplate: String!\n  detailLinkCopied: String!\n  detailCopyFailedManual: String!\n  detailDisbandConfirmTitle: String!\n  detailDisbandConfirmMessageTemplate: String!\n  # 完成 / 恢复 (完成态: 列表隐藏 + 不再提醒; 详情直达可打开, 车头可恢复)\n  detailCompleteLabel: String!\n  detailCompletingLabel: String!\n  detailStatusCompletedLabel: String!\n  detailRestoreLabel: String!\n  detailCompleteConfirmTitle: String!\n  detailCompleteConfirmMessageTemplate: String!\n  detailToastCompleted: String!\n  detailToastCompleteFailedTemplate: String!\n  detailToastRestored: String!\n  detailToastRestoreFailedTemplate: String!\n  detailCompletedHint: String!\n  confirmOkLabel: String!\n  confirmCancelLabel: String!\n  typeShortActivity: String!\n  typeShortTalent: String!\n  typeShortRace: String!\n  typeShortTower: String!\n  typeShortGather: String!\n  typeShortExplore: String!\n  # 座位文案\n  seatEmptyJoinLabel: String!\n  seatEmptyLabel: String!\n  seatModalTitleTemplate: String!\n  seatModalSubtitle: String!\n  seatNameLabel: String!\n  seatNamePlaceholder: String!\n  seatNameRequired: String!\n  # 报名身份收口: 自己报名 (名字锁定) / 代报名 (名册选人) 双模式文案\n  seatSelfTabLabel: String!\n  seatProxyTabLabel: String!\n  seatSelfNameHint: String!\n  seatProxySearchPlaceholder: String!\n  seatProxyPickRequired: String!\n  seatProxyEmptyText: String!\n  seatSectLabel: String!\n  seatCancelLabel: String!\n  seatConfirmJoinLabel: String!\n  seatJoiningLabel: String!\n  seatLeaderLabel: String!\n  seatToastSect: String!\n  seatToastJoined: String!\n  seatToastJoinFailedTemplate: String!\n  seatToastLeft: String!\n  seatToastLeaveFailedTemplate: String!\n  seatLeaveConfirmTitle: String!\n  seatLeaveConfirmMessageTemplate: String!\n  # 就位 (发车提醒) 文案\n  detailReadyProgressTemplate: String!\n  seatReadyLabel: String!\n  seatReadyActionLabel: String!\n  seatUnreadyActionLabel: String!\n  seatToastReady: String!\n  seatToastUnready: String!\n  seatToastReadyFailedTemplate: String!\n  # 编辑表单文案 (与列表页 shell 同名同口径)\n  formCreateTitle: String!\n  formEditTitle: String!\n  formTypeLabel: String!\n  formTypeActivityLabel: String!\n  formTypeTalentLabel: String!\n  formTypeRaceLabel: String!\n  formTypeTowerLabel: String!\n  formCapacityTemplate: String!\n  formHintActivity: String!\n  formHintDungeonTemplate: String!\n  formHintTalent: String!\n  formHintRace: String!\n  formHintTower: String!\n  formTitleLabel: String!\n  formTitlePlaceholder: String!\n  formStartsLabel: String!\n  formMonthTemplate: String!\n  formDayTemplate: String!\n  formHourTemplate: String!\n  formMinuteTemplate: String!\n  formDungeonLabel: String!\n  formDungeonNoneLabel: String!\n  formNicknameLabel: String!\n  formNicknamePlaceholder: String!\n  formSectLabel: String!\n  formCancelLabel: String!\n  formSubmitCreateLabel: String!\n  formSubmitEditLabel: String!\n  formSubmittingLabel: String!\n  formToastSect: String!\n  formToastSaved: String!\n  formToastSaveFailedTemplate: String!\n  formToastPosted: String!\n  formToastCreateFailedTemplate: String!\n  formTitleTemplate: String!\n  formCustomFieldsTitle: String!\n  formCustomFieldAddLabel: String!\n  formCustomFieldLabelPlaceholder: String!\n  formCustomFieldTypeText: String!\n  formCustomFieldTypeChoice: String!\n  formCustomFieldOptionsPlaceholder: String!\n  formCustomFieldRequiredLabel: String!\n  formCustomFieldRemoveLabel: String!\n  formCustomFieldEmptyText: String!\n}\n\n# 管理动作 (编辑/完成/恢复/解散) 的文案组: 只随 GroupingDetailPage\n# .manageActions 下发, 对象在场本身即管理判定结果 (非权限标志)。\ntype GroupingManageActions {\n  editLabel: String!\n  completeLabel: String!\n  completingLabel: String!\n  restoreLabel: String!\n  disbandLabel: String!\n  disbandingLabel: String!\n  disbandConfirmTitle: String!\n  disbandConfirmMessageTemplate: String!\n  completeConfirmTitle: String!\n  completeConfirmMessageTemplate: String!\n}\n\n# ============ 页面：攻略（图鉴） ============\n# URL: /{slug}/dex\n\nextend type Query {\n  dexPage: DexPage!\n}\n\ntype DexPage {\n  sectOptions: [SectOption!]!  # 流派选项 (slug + 规范名): 选中值会被存储的挑选器用 (组队报名/建车/管理攻略), 规范名不做 locale 覆盖\n  current: [Dungeon!]!  # server 按 dungeons.version = settings.game_version_code (版本码, 如 intl-v2.3) 过滤\n  past: [Dungeon!]!     # version != game_version_code\n  currentVersion: String!  # 展示串 (settings.game_version, 如「国际服 V2.3「青州」」), 非版本码, 勿用于比较\n  categories: [DexCategory!]!  # 游戏内分类分组 (传薪→铸矩→鉴心→梦洄→试锋), 组内按等级降序\n  # UI 文案 (shell gen 方法按请求 locale 生成)\n  dexBackLabel: String!\n  dexBossesLineTemplate: String!\n  dexNoBossDataText: String!\n  dexEmptyText: String!\n  dexCurrentGuidesTemplate: String!\n  dexCatSubTemplate: String!\n  dexCatSubCurrentTemplate: String!\n  dexSize10Label: String!\n  dexSize5Label: String!\n  dexSizeNTemplate: String!\n  dexBossUnit: String!\n  dexPartMechanicsLabel: String!\n  dexPartShoutsLabel: String!\n  dexPartTalentsLabel: String!\n  dexLabelAllTemplate: String!\n  dexLabelPartsTemplate: String!\n  dexLabelPendingTemplate: String!\n  dexLabelNoBossesText: String!\n  dexSealBossText: String!\n}\n\n# 攻略分类组: 游戏内分类 (试锋/梦洄/鉴心/铸矩/传薪) 与赛季一一对应, 标签全部由后端下发\ntype DexCategory {\n  category: String!     # 试锋 / 梦洄 / 鉴心 / 铸矩 / 传薪\n  season: String!       # S1..S5\n  seasonName: String!   # 赛季展示名 (同 Dungeon.seasonName 口径)\n  isCurrent: Boolean!   # 传薪 = 当期分类\n  dungeons: [Dungeon!]!\n}\n\n# ============ 页面：Boss 攻略详情 ============\n# URL: /{slug}/boss/{id}\n\nextend type Query {\n  bossPage(bossId: ID!): BossPage!\n}\n\ntype BossPage {\n  boss: Boss!\n  defaultTab: DexTab!\n  # UI 文案 (shell gen 方法按请求 locale 生成)\n  bossBackLabel: String!\n  bossNotFoundText: String!\n  bossTabMechanicsLabel: String!\n  bossTabTalentsLabel: String!\n  bossShoutsTitle: String!\n  bossCopyLabel: String!\n  bossShoutCopiedText: String!\n  bossCopyFailedText: String!\n  bossCopyManualText: String!\n  bossNoMechanicsText: String!\n  bossNoTalentsText: String!\n  bossTalentTitleTemplate: String!\n  bossTalentPendingSuffix: String!\n}\n\n# ============ 页面：流派攻略 ============\n# URL: /{slug}/sects (嵌入公会主页 Tab)\n\nextend type Query {\n  sectPage: SectPage!\n  affixMaxList: [AffixMax!]!\n  slotAffixList(build: String!): [SlotAffix!]!\n}\n\ntype AffixMax {\n  key: String!\n  name: String!\n  maxValue: Float!\n  unit: String!\n}\n\ntype SlotAffix {\n  slot: String!\n  affixKey: String!\n}\n\ntype SectGroup {\n  key: String!    # 门派稳定键 (slug 家族前缀, 如 mingjin)\n  label: String!  # 门派展示名 (按 locale 覆盖后的家族名)\n}\n\ntype SectPage {\n  sects: [Sect!]!\n  sectGroups: [SectGroup!]!  # 实际出现的门派分组 (规范顺序, 索引页分组渲染用)\n  # UI 文案 (shell gen 方法按请求 locale 生成)\n  sectEmptyText: String!\n  sectBackLabel: String!\n  sectTabBisLabel: String!\n  sectTabRotationLabel: String!\n  sectTabRatesLabel: String!\n  sectTabTiaolvLabel: String!\n  sectTabGradLabel: String!\n  sectNoBisText: String!\n  sectNoRotationText: String!\n  sectNoRatesText: String!\n  sectRotGreydustLabel: String!\n  sectRotOpenerLabel: String!\n  sectRotLoopLabel: String!\n  sectRotKeyPointsLabel: String!\n  sectRotInnerSkillsLabel: String!\n  sectRotVideoLabel: String!\n  sectRateAccuracyLabel: String!\n  sectRateCritLabel: String!\n  sectRateCritDamageLabel: String!\n  sectBisMainWeaponLabel: String!\n  sectBisOffWeaponLabel: String!\n  sectBisAccessoriesLabel: String!\n  sectBisHeadBodyLabel: String!\n  sectBisLegsWristsLabel: String!\n  sectTabAffixLabel: String!\n  sectAffixEmptyText: String!\n  sectAffixSetLabel: String!\n  sectAffixBowLabel: String!\n  sectAffixDingyinLabel: String!\n  sectAffixColAffixLabel: String!\n  sectAffixColCountLabel: String!\n  sectAffixColMaxLabel: String!\n  sectAffixColCyLabel: String!\n  sectAffixSourceText: String!\n}\n\ntype Sect {\n  slug: String!       # 英文 slug，如 pozhu-zun\n  groupKey: String!   # 门派稳定键 (与 SectPage.sectGroups 对应)\n  name: String!        # 中文名，如 破竹·樽\n  weapons: String!\n  buildType: String!  # 会心流 / 会意流 / 治疗\n  bis: BisTable        # 毕业词条\n  rotation: Rotation   # 输出轴\n  rateTargets: RateTargets  # 三率目标\n  gradBuilds: [SectGradBuild!]!  # 毕业词缀：本流派 100 阶毕业配方的词缀构成（配装台口径）\n}\n\n# 一个流派的一条毕业配方（构筑变体）：词缀构成 = targets 条数表\ntype SectGradBuild {\n  name: String!        # 构筑名，如 牵丝-霖（纯奶）（按 locale 本地化流派名）\n  cat: String!         # 流派大类：大外会意 / 大外会心 / 小外会心\n  setName: String!     # 套装\n  bowLabel: String     # 推荐弓玦，如 精准弓\n  recipe: String!      # 配方原文，如 \"1剑增 + 2首领 + 2全武 + 12大外 + ...\"\n  note: String         # 配方备注（原站注记，可空）\n  dingyinName: String  # 武学定音名（已证实者才有；未证实为 null）\n  totalBars: Int!      # 总条数（恒 40）\n  targets: [SectGradTarget!]!\n}\n\ntype SectGradTarget {\n  label: String!          # 词缀全名，如 大外功（按 locale 本地化）\n  count: Int!             # 条数\n  maxValue: Float         # 单条满值（属攻/二选一类无统一满值，为 null）\n  cyValue: Float          # 单条承音值（同上）\n  unit: String!           # 单位（% 或空串）\n  flexLabels: [String!]! # 二选一目标的候选词缀全名（非二选一时为空）\n}\n\ntype BisTable {\n  # 按部位：主武器/副武器/环佩/头衣/腿腕\n  # 每部位 5 词条，首个为初始锁定\n  mainWeapon: [String!]!\n  offWeapon: [String!]!\n  accessories: [String!]!\n  headBody: [String!]!\n  legsWrists: [String!]!\n}\n\ntype Rotation {\n  greydust: String     # greydust 1分钟木桩轴\n  opener: String       # 起手（详细版）\n  loop: String         # 循环（详细版）\n  keyPoints: String    # 要点（详细版）\n  innerSkills: String  # 心法（详细版）\n  videoUrl: String\n}\n\ntype RateTargets {\n  accuracy: String\n  crit: String\n  critDamage: String  # 会意\n  note: String\n}\n\n# ============ 页面：调律推演 ============\n# URL: /{slug}/tiaolv\n\nextend type Query {\n  tiaolvPage: TiaolvPage!\n}\n\n# 闭集词汇选项: 客户端以 id 为键 (状态/入参), label 只作展示\ntype TiaolvVocabOption {\n  id: String!        # 稳定 id (none/hantian/self/common …)\n  label: String!     # 展示名 (游戏术语为规范名; \"无\" 项走 locale 文案)\n  isDefault: Boolean!\n}\n\n# 调律网格行: Excel 行号 -> 属性标签 (游戏数据, 不本地化)\ntype TiaolvTuneRow {\n  row: Int!\n  label: String!\n}\n\n# 流派 -> 默认武学名 (Excel F14, 游戏数据)\ntype TiaolvSectWuxue {\n  sectSlug: String!\n  wuxue: String!\n}\n\ntype TiaolvPage {\n  sects: [SectOption!]!\n  innerSkills: [String!]!\n  suits: [String!]!\n  # 闭集词汇 (后端单一真源, 前端不持有副本)\n  tlSuitOptions: [TiaolvVocabOption!]!   # 套装 (id 发给 calcTiaolv, 服务端译回规范名)\n  tlBowOptions: [TiaolvVocabOption!]!    # 弓 (none = 不带弓, 入参发 null)\n  tlWukuOptions: [TiaolvVocabOption!]!   # 武库 (self 本系 / common 通用)\n  tlTuneRows: [TiaolvTuneRow!]!          # 调律网格属性行\n  tlSectWuxue: [TiaolvSectWuxue!]!       # 流派默认武学\n  # 毕业满值常量（服务端下发，前端不硬编码）\n  maxValues: TiaolvMaxValues!\n  # 流派权重（服务端下发）\n  sectWeights: [SectWeight!]!\n  # UI 文案 (shell gen 方法按请求 locale 生成)\n  tlIntroText: String!\n  tlInnerSkillTemplate: String!\n  tlInnerSkillPlaceholder: String!\n  tlWuxueLabel: String!\n  tlWukuLabel: String!\n  tlWukuSelfLabel: String!\n  tlWukuCommonLabel: String!\n  tlSuitLabel: String!\n  tlBowLabel: String!\n  tlNoneLabel: String!\n  tlTuneAreaLabel: String!\n  tlCalcLabel: String!\n  tlCalculatingLabel: String!\n  tlToastFailedText: String!\n  tlToastFailedWithTemplate: String!\n  tlColAttrLabel: String!\n  tlColBaseLabel: String!\n  tlColPanelLabel: String!\n  tlColFinalLabel: String!\n}\n\n# ============ 页面：武库鉴宝 (毕业率) ============\n# UI 文案专用 shell (数据走 affixMaxList / slotAffixList / calcGraduation)\n\nextend type Query {\n  gradPage: GradPage!\n}\n\n# ============ 页面：设置 (账号级语言偏好) ============\n# 文案字段直接长在 SettingsPage shell 上, 由其 gen 方法按请求 locale 生成;\n# localePref = 账号存储的偏好 (null = 自动/跟随浏览器), effectiveLocale =\n# 本请求实际生效 locale (偏好压过浏览器语言)。\n\nextend type Query {\n  settingsPage: SettingsPage!\n}\n\ntype SettingsPage {\n  settingsTitle: String!\n  settingsDiscordLabel: String!\n  settingsLanguageLabel: String!\n  settingsLanguageHint: String!\n  settingsAutoLabel: String!\n  settingsLangZhCnLabel: String!\n  settingsLangZhTwLabel: String!\n  settingsLangEnLabel: String!\n  settingsLangEsLabel: String!\n  settingsLangFrLabel: String!\n  settingsSavedText: String!\n  # 意见反馈: 个人资料内的入口 + 表单文案 (类别枚举见 FeedbackCategory)\n  feedbackEntryLabel: String!\n  feedbackTitle: String!\n  feedbackCategoryLabel: String!\n  feedbackCategoryProblemLabel: String!\n  feedbackCategorySuggestionLabel: String!\n  feedbackCategoryOtherLabel: String!\n  feedbackPlaceholder: String!\n  feedbackSubmitLabel: String!\n  feedbackSubmittingLabel: String!\n  feedbackSuccessText: String!\n  localePref: String\n  effectiveLocale: String!\n  # ---- 我的数据 (账号导出 / 删除自助) ----\n  accountSectionTitle: String!\n  accountExportLabel: String!\n  accountExportHint: String!\n  accountDeleteLabel: String!\n  accountDeleteHint: String!\n  accountReauthLabel: String!\n  accountReauthHint: String!\n  accountConfirmTitle: String!\n  accountConfirmIntro: String!\n  accountConsequenceCars: String!\n  accountConsequenceData: String!\n  accountConsequenceGuilds: String!\n  accountConsequenceResidual: String!\n  accountConsequenceReregister: String!\n  accountExportFirstHint: String!\n  accountUsernameLabel: String!\n  accountSubmitLabel: String!\n  accountBackLabel: String!\n  accountCancelDeletionLabel: String!\n  accountDeletionRequestedText: String!\n  accountDeletionCancelledText: String!\n  # 我的赛季目标 (F19): 成员给自己设的目标, 挂在设置语境 (设置\n  # dialog 的一个 dialogPage); 目标实体与文案见 MySeasonGoalPage。\n  seasonGoals: MySeasonGoalPage!\n  # 最近一次完成 Discord OAuth 往返的 epoch 秒 (null = 从未); 导出与\n  # 删除提交要求 10 分钟内的新鲜授权, 闸门在 mutation 服务端强制,\n  # 此字段只供界面决定先展示哪一步。\n  freshAuthAt: Int\n  # 待删除状态只由「在场」表达: 有未到期 (或已到期待执行) 的删除\n  # 申请时此对象存在, 否则为 null — 前端不拿标志位自判。\n  accountPendingDeletion: AccountPendingDeletion\n  # ---- 我的可用时间 (F5 编辑面归位个人设置): 文案与排期页同一组\n  # schedule 目录字符串; 数据按本人所属百业逐份下发, 编辑仍走\n  # setMyAvailability (同一实体、同一时区口径), 此处只是新落点。\n  availabilityTitle: String!\n  availabilityHint: String!\n  availabilityWeekdayNames: [String!]!\n  availabilityAddSlotLabel: String!\n  availabilityRemoveLabel: String!\n  availabilitySaveLabel: String!\n  availabilitySavedText: String!\n  availabilitySaveFailedTemplate: String!\n  availabilityEmptyText: String!\n  availabilityNoGuildsText: String!\n  availabilityGuilds: [SettingsAvailabilityGuild!]!\n}\n\n# 设置页里的一份可用时间: 一个本人所属百业 + 已存的 UTC 周时段。\ntype SettingsAvailabilityGuild {\n  slug: String!\n  guildName: String!\n  slots: [AvailabilitySlot!]!\n}\n\n# 冷静期中的删除申请: executesAt 为执行时刻 (ISO), daysLeft 为剩余\n# 整天数; 文案在服务端按 locale 组合 (pendingBody 已含执行日期)。\ntype AccountPendingDeletion {\n  executesAt: String!\n  daysLeft: Int!\n  accountPendingTitle: String!\n  accountPendingBody: String!\n}\n\nenum FeedbackCategory {\n  PROBLEM\n  SUGGESTION\n  OTHER\n}\n\ntype SubmitFeedbackPayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n}\n\nextend type Mutation {\n  # 站内反馈: 身份只从会话解析; 内容去空白后非空且不超过 2000 字,\n  # 同一用户滚动 24 小时内上限 5 条 (错误码 feedbackEmpty /\n  # feedbackTooLong / feedbackRateLimited, 文案走 errors 目录)\n  submitFeedback(category: FeedbackCategory!, text: String!): SubmitFeedbackPayload!\n}\n\ntype UpdateLocalePayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n  localePref: String\n  effectiveLocale: String!\n}\n\nextend type Mutation {\n  # locale 为 null 时清除偏好 (回自动); 有值必须是受支持 locale id\n  updateMyLocale(locale: String): UpdateLocalePayload!\n}\n\ntype ExportMyDataPayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n  # 导出文档全文 (JSON 字符串, user-export v1); 失败时为 null\n  json: String\n  filename: String\n}\n\ntype AccountDeletionPayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n  # 提交成功时的执行时刻 (ISO); 撤销成功时为 null\n  executesAt: String\n}\n\nextend type Mutation {\n  # 导出我的数据: 需登录 + 10 分钟内的新鲜 Discord 授权; 每 24 小时\n  # 至多一次 (以 account.export 审计行计数)。凭据永不进导出包。\n  exportMyData: ExportMyDataPayload!\n  # 提交账号删除: 需新鲜授权 + 键入本人 Discord 显示名; 进入 7 天\n  # 冷静期, 到期由每日任务执行级联。\n  requestAccountDeletion(typedUsername: String!): AccountDeletionPayload!\n  # 撤销冷静期中的删除申请。\n  cancelAccountDeletion: AccountDeletionPayload!\n}\n\ntype PushTokenPayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n}\n\nextend type Mutation {\n  # App 推送令牌 (发车提醒的 Expo 通道): 身份只从会话解析, 令牌格式服务端校验\n  registerPushToken(token: String!, platform: String): PushTokenPayload!\n  unregisterPushToken(token: String!): PushTokenPayload!\n}\n\n# 毕业率槽位: id 为客户端状态键/入参 (calcGraduation 原样回显), label 为规范槽位名 (数据键)\ntype GradSlot {\n  id: String!\n  label: String!\n  icon: String!\n}\n\n# 三率行: key = GraduationInput 字段名, cap = 达标满值\ntype GradRate {\n  key: String!\n  label: String!\n  cap: Float!\n}\n\n# OCR 兜底: 读到 needle 而未命中全名时, 规范化为 name\ntype GearOcrFallback {\n  needle: String!\n  name: String!\n}\n\n# 装备库/OCR 规则束 (后端单一真源): 武器池与识别规则的规范名全部在此\ntype GearVocabRules {\n  weaponSlot: String!            # 武器类规范槽位名 (主/副武器归一后的类别)\n  weaponPositions: [String!]!    # 武器可占的装备位 (规范名)\n  ocrStripPrefixes: [String!]!   # OCR 词条名需剥离的大小前缀\n  ocrDingyinMarker: String!      # 定音段标记词\n  ocrDingyinFallbacks: [GearOcrFallback!]!\n}\n\ntype GradPage {\n  gradSlots: [GradSlot!]!        # 8 槽位 (顺序 = 客户端方案按位对齐序, 不可变)\n  gradRates: [GradRate!]!        # 三率行 (精准/会心/会意)\n  gearVocabRules: GearVocabRules!\n  gradEnteringText: String!\n  gradTitle: String!\n  gradSubtitle: String!\n  gradMingjinNote: String!\n  gradBuildBigLabel: String!\n  gradBuildSmallLabel: String!\n  gradRingLabel: String!\n  gradScoreCountLabel: String!\n  gradScoreValueLabel: String!\n  gradScoreRateLabel: String!\n  gradTier1: String!\n  gradTier2: String!\n  gradTier3: String!\n  gradTier4: String!\n  gradTier5: String!\n  gradTier6: String!\n  gradTapHint: String!\n  gradRefTitle: String!\n  gradMaxTableTitle: String!\n  gradColAffixLabel: String!\n  gradColMaxLabel: String!\n  gradColResonanceLabel: String!\n  gradSlotTableTitleTemplate: String!\n  gradRateTitle: String!\n  gradRateOkTemplate: String!\n  gradRateGapTemplate: String!\n  gradRateOverflowTemplate: String!\n  gradCompareTitle: String!\n  gradSaveSchemeLabel: String!\n  gradSchemeNameTemplate: String!\n  gradNoSchemesText: String!\n  gradLoadLabel: String!\n  gradDeleteSchemeLabel: String!\n  gradCloseLabel: String!\n  gradItemScoreTemplate: String!\n  gradRowMainLabel: String!\n  gradRowSubTemplate: String!\n  gradRowResonanceLabel: String!\n  gradAffixPlaceholder: String!\n  gradAffixLoadingText: String!\n  gradValuePlaceholderMaxTemplate: String!\n  gradValuePlaceholder: String!\n  gradResonanceLabel: String!\n  gradOverMaxTemplate: String!\n  gradToastSavedTemplate: String!\n  gradToastLoadedTemplate: String!\n  gradToastOldSchemeText: String!\n  gradConfirmLabel: String!\n  gradCancelLabel: String!\n  # ---- 配装台 (gear-planner 移植; 并入本页, 数据/文案均由 GradPage shell gen) ----\n  gearSlots: [String!]!\n  gearGearSlots: [String!]!\n  gearAffixes: [GearAffixRow!]!\n  gearBuilds: [GearBuild!]!\n  gearSlotsBig: [GearSlotRow!]!\n  gearSlotsSmall: [GearSlotRow!]!\n  gearBaseFields: [GearBaseField!]!\n  gearXinfa: [GearXinfaRow!]!\n  gearTalentRows: [GearTalentRow!]!\n  gearDingyinRows: [GearDingyinRow!]!\n  gearDingyinLeft: [GearNameMax!]!\n  gearDingyinRightMax: Float!\n  gearWuxueNames: [String!]!\n  gearBows: [GearBowRow!]!\n  gearPasteNames: [GearNameKey!]!\n  gearNameToClass: [GearNameCls!]!\n  gearSlotAliases: [GearNameKey!]!\n  gearOcrAliases: [GearNameKey!]!\n  gearLegacyKeys: [GearNameKey!]!\n  gearClassLabels: [GearNameCls!]!\n  gearSchoolTags: [String!]!\n  gearDemoKit: [GearDemoItem!]!\n  gearDimRows: [GearDimRow!]!\n  gearQuickBarNames: [String!]!\n  gearResDefault: Float!\n  gearBenchTitle: String!\n  gearCalcLabel: String!\n  gearBenchIntro: String!\n  gearTargetLabel: String!\n  gearBowLabel: String!\n  gearBowNoneLabel: String!\n  gearExtrasTitle: String!\n  gearResLabel: String!\n  gearExtraAccLabel: String!\n  gearExtraCritLabel: String!\n  gearExtraIntLabel: String!\n  gearBaseTitle: String!\n  gearUnlockLabel: String!\n  gearLockLabel: String!\n  gearModifiedTag: String!\n  gearBaseResetLabel: String!\n  gearBaseResetTitle: String!\n  gearBaseResetBody: String!\n  gearXinfaLabelTemplate: String!\n  gearXinfaNoneLabel: String!\n  gearLibTitle: String!\n  gearMyLibTitle: String!\n  gearMyBuildsTitle: String!\n  gearLoginHint: String!\n  gearLibCountTemplate: String!\n  gearUsageCount: Int!\n  gearUsageLimit: Int!\n  gearUsageTemplate: String!\n  gearUsageNearLimitText: String!\n  gearFormSlotLabel: String!\n  gearFormNameLabel: String!\n  gearFormNamePlaceholder: String!\n  gearAffixPlaceholder: String!\n  gearValuePlaceholder: String!\n  gearRefTemplate: String!\n  gearFillMaxLabel: String!\n  gearFillCyLabel: String!\n  gearDelRowLabel: String!\n  gearAddRowLabel: String!\n  gearDyNameLabel: String!\n  gearDyNamePlaceholder: String!\n  gearDyValLabel: String!\n  gearSchoolsLabel: String!\n  gearAddGearLabel: String!\n  gearUpdateGearLabel: String!\n  gearCancelEditLabel: String!\n  gearDemoLabel: String!\n  gearClearLibLabel: String!\n  gearClearConfirmTitle: String!\n  gearClearConfirmBody: String!\n  gearEquipLabel: String!\n  gearUnequipLabel: String!\n  gearEditLabel: String!\n  gearDeleteLabel: String!\n  gearSimLabel: String!\n  gearSimRealLabel: String!\n  gearSimCyLabel: String!\n  gearSimMaxLabel: String!\n  gearVerdictHeirloom: String!\n  gearVerdictDud: String!\n  gearScoreTemplate: String!\n  gearQualityLabel: String!\n  gearExportLabel: String!\n  gearExportFileName: String!\n  gearImportNameTemplate: String!\n  gearImportLabel: String!\n  gearImportFailedToast: String!\n  gearImportedToastTemplate: String!\n  gearManualTitle: String!\n  gearPasteTitle: String!\n  gearPastePlaceholder: String!\n  gearPasteButtonLabel: String!\n  gearPasteDemoLabel: String!\n  gearPasteEmptyText: String!\n  gearPasteOkTemplate: String!\n  gearPasteUnknownTemplate: String!\n  gearPasteFailText: String!\n  gearPasteFullText: String!\n  gearOcrTitle: String!\n  gearOcrDropText: String!\n  gearOcrPreparingText: String!\n  gearOcrRunningText: String!\n  gearOcrSecondText: String!\n  gearOcrFailedText: String!\n  gearOcrBadTypeText: String!\n  gearOcrTooBigText: String!\n  gearOcrNoEngineText: String!\n  gearOcrDoneTemplate: String!\n  gearOcrSlotLabel: String!\n  gearOcrNameLabel: String!\n  gearOcrEquipLabel: String!\n  gearOcrConfirmLabel: String!\n  gearOcrCancelLabel: String!\n  gearOcrUnknownTitle: String!\n  gearOcrSavedTemplate: String!\n  gearOcrNeedLineToast: String!\n  gearOcrLowConfTag: String!\n  gearOcrAddRowLabel: String!\n  gearOcrImportSlotTemplate: String!\n  gearOcrBatchTitle: String!\n  gearOcrBatchDropText: String!\n  gearOcrBatchQueuedText: String!\n  gearOcrBatchRunningText: String!\n  gearOcrBatchReadyText: String!\n  gearOcrBatchFailedText: String!\n  gearOcrBatchImportedText: String!\n  gearOcrBatchRetryLabel: String!\n  gearOcrBatchRemoveLabel: String!\n  gearOcrBatchAdjustLabel: String!\n  gearOcrBatchApplyBoxLabel: String!\n  gearOcrBatchDetectedText: String!\n  gearOcrBatchFullImageText: String!\n  gearOcrBatchDupTag: String!\n  gearOcrBatchDupLibText: String!\n  gearOcrBatchDupRowText: String!\n  gearOcrBatchIncludeLabel: String!\n  gearOcrBatchNoLinesText: String!\n  gearOcrBatchImportTemplate: String!\n  gearOcrBatchResultTemplate: String!\n  gearLibEmptyText: String!\n  gearEquippedTag: String!\n  gearLoadoutTitle: String!\n  gearAutoLabel: String!\n  gearAutoDoneToast: String!\n  gearAutoFallbackToast: String!\n  gearUnequipAllLabel: String!\n  gearSlotEmptyText: String!\n  gearPanelTitle: String!\n  gearGradLabel: String!\n  gearGradCountLabel: String!\n  gearGradValueLabel: String!\n  gearGradDyLabel: String!\n  gearGradDyToggleLabel: String!\n  gearLoanLabel: String!\n  gearSimActiveTag: String!\n  gearCopySummaryLabel: String!\n  gearCopiedToast: String!\n  gearCopyFailedToast: String!\n  gearYAccLabel: String!\n  gearYCritLabel: String!\n  gearYIntLabel: String!\n  gearFinalCritLabel: String!\n  gearWhiteLabel: String!\n  gearDawaiLabel: String!\n  gearXiaowaiLabel: String!\n  gearDashuLabel: String!\n  gearXiaoshuLabel: String!\n  gearHpLabel: String!\n  gearDefLabel: String!\n  gearTalentLabel: String!\n  gearDiffTitle: String!\n  gearDiffLackTemplate: String!\n  gearDiffExactText: String!\n  gearDiffOverTemplate: String!\n  gearDiffExtraTitle: String!\n  gearDiffLowTitle: String!\n  gearDiffDoneText: String!\n  gearDiffEmptyText: String!\n  gearDiffInvalidTemplate: String!\n  gearSuggestTitle: String!\n  gearSuggestSwapTemplate: String!\n  gearSuggestWashTemplate: String!\n  gearSuggestNoneText: String!\n  gearSuggestHeadTemplate: String!\n  gearDySummaryTitle: String!\n  gearDyCorrectText: String!\n  gearDyWrongText: String!\n  gearSchemeTitle: String!\n  gearSchemeSaveLabel: String!\n  gearSchemeNameTemplate: String!\n  gearSchemeLoadLabel: String!\n  gearSchemeDeleteLabel: String!\n  gearSchemeEmptyText: String!\n  gearSchemeComposeFirstText: String!\n  gearSchemeSavedToastTemplate: String!\n  gearSchemeLoadedToastTemplate: String!\n  gearSchemeGroupCountTemplate: String!\n  gearShareLabel: String!\n  gearRevokeShareLabel: String!\n  gearCopyLinkLabel: String!\n  gearShareRevokedToast: String!\n  gearQuickTitle: String!\n  gearQuickResLabel: String!\n  gearQuickSyncLabel: String!\n  gearQuickSyncedToast: String!\n  gearQuickOkText: String!\n  gearQuickOverTemplate: String!\n  gearQuickGapTemplate: String!\n  gearRecipesTitle: String!\n  gearRecipeSearchPlaceholder: String!\n  gearRecipeAllLabel: String!\n  gearRecipeColCat: String!\n  gearRecipeColSchool: String!\n  gearRecipeColSet: String!\n  gearRecipeColRecipe: String!\n  gearRecipeColBow: String!\n  gearRecipeSetTargetLabel: String!\n  gearRecipeEmptyText: String!\n  gearRecipeTargetToastTemplate: String!\n  gearSectRecipesTitle: String!\n  gearAffixTableTitle: String!\n  gearColCyLabel: String!\n  gearColCyPctLabel: String!\n  gearColRecipeNamesLabel: String!\n  gearSurvivalNote: String!\n  gearSlotTableTitle: String!\n  gearSlotsBigTitle: String!\n  gearSlotsSmallTitle: String!\n  gearFormulaTitle: String!\n  gearFormulaRatesTitle: String!\n  gearFormulaDimsTitle: String!\n  gearFormulaOrderTitle: String!\n  gearFormulaAccTemplate: String!\n  gearFormulaCritTemplate: String!\n  gearFormulaIntTemplate: String!\n  gearFormulaBarsTemplate: String!\n  gearFormulaBowTemplate: String!\n  gearFormulaOrderText: String!\n  gearColDimLabel: String!\n  gearColConvLabel: String!\n  gearColFullBarTemplate: String!\n  gearCalcFailedText: String!\n  gearDemoLoadedToast: String!\n  gearSavedToastTemplate: String!\n  gearDeletedToast: String!\n  gearClearedToast: String!\n}\n\ntype SectOption {\n  slug: String!\n  name: String!\n}\n\ntype TiaolvMaxValues {\n  mainAttr: Float!   # 88.4\n  outerAtk: Float!   # 139.6\n  accuracy: Float!   # 0.144\n  crit: Float!       # 0.162\n  critDamage: Float! # 0.081\n  sectAttr: Float!   # 79.2\n}\n\ntype SectWeight {\n  sectSlug: String!\n  critWeight: Float!\n  critDamageWeight: Float!\n  # 其他权重...\n}\n\n# ============ 页面：百业排期 (F5 可用时间 + F13 时间投票) ============\n# URL: /{slug} 的排期页签。成员填自己的每周可用时段 (UTC 存储,\n# 客户端按本地时区渲染); 汇总只下发给百业管理员与在本百业发过车\n# 的车头 (其他观看者 availabilitySummary 为 null)。时间投票是多选\n# 可用式投票: 成员勾选所有能参加的候选, 票数实时汇总; 发起人或\n# 百业管理员可关闭。投票只产出建议, 定档仍由人点选发车。\n\nextend type Query {\n  guildSchedulePage(slug: String!): GuildSchedulePage!\n}\n\ntype GuildSchedulePage {\n  slug: String!\n  # 本人可用时段 (UTC 周内分钟窗; 未登录/未填为 [])\n  myAvailability: [AvailabilitySlot!]!\n  # 成员可用性汇总: 仅管理员/车头非 null (权限结论由字段在否表达)\n  availabilitySummary: [MemberAvailabilitySummary!]\n  polls: [TimePoll!]!\n  weekdayNames: [String!]!\n  # 发车表单文案 (以投票时间发车时预填同一个建车表单, 与列表页同口径)\n  formCreateTitle: String!\n  formEditTitle: String!\n  formTypeLabel: String!\n  formTypeActivityLabel: String!\n  formTypeTalentLabel: String!\n  formTypeRaceLabel: String!\n  formTypeTowerLabel: String!\n  formCapacityTemplate: String!\n  formHintActivity: String!\n  formHintDungeonTemplate: String!\n  formHintTalent: String!\n  formHintRace: String!\n  formHintTower: String!\n  formTitleLabel: String!\n  formTitlePlaceholder: String!\n  formStartsLabel: String!\n  formMonthTemplate: String!\n  formDayTemplate: String!\n  formHourTemplate: String!\n  formMinuteTemplate: String!\n  formDungeonLabel: String!\n  formDungeonNoneLabel: String!\n  formNicknameLabel: String!\n  formNicknamePlaceholder: String!\n  formSectLabel: String!\n  formCancelLabel: String!\n  formSubmitCreateLabel: String!\n  formSubmitEditLabel: String!\n  formSubmittingLabel: String!\n  formToastSect: String!\n  formToastSaved: String!\n  formToastSaveFailedTemplate: String!\n  formToastPosted: String!\n  formToastCreateFailedTemplate: String!\n  formTitleTemplate: String!\n  formCustomFieldsTitle: String!\n  formCustomFieldAddLabel: String!\n  formCustomFieldLabelPlaceholder: String!\n  formCustomFieldTypeText: String!\n  formCustomFieldTypeChoice: String!\n  formCustomFieldOptionsPlaceholder: String!\n  formCustomFieldRequiredLabel: String!\n  formCustomFieldRemoveLabel: String!\n  formCustomFieldEmptyText: String!\n  typeShortActivity: String!\n  typeShortTalent: String!\n  typeShortRace: String!\n  typeShortTower: String!\n  # 排期页文案\n  scheduleTitle: String!\n  scheduleMyTitle: String!\n  scheduleMyHint: String!\n  scheduleSlotRangeTemplate: String!\n  scheduleAddSlotLabel: String!\n  scheduleRemoveLabel: String!\n  scheduleSaveLabel: String!\n  scheduleSavedText: String!\n  scheduleSaveFailedTemplate: String!\n  scheduleEmptyMineText: String!\n  scheduleSummaryTitle: String!\n  scheduleSummaryHint: String!\n  scheduleSummaryEmptyText: String!\n  schedulePollsTitle: String!\n  schedulePollsHint: String!\n  schedulePollEmptyText: String!\n  schedulePollCreateLabel: String!\n  schedulePollTitleLabel: String!\n  schedulePollTitlePlaceholder: String!\n  schedulePollCandidatesLabel: String!\n  schedulePollAddCandidateLabel: String!\n  schedulePollSubmitLabel: String!\n  schedulePollVoteLabel: String!\n  schedulePollVotedText: String!\n  schedulePollStatusOpenText: String!\n  schedulePollStatusClosedText: String!\n  schedulePollCloseLabel: String!\n  schedulePollVoteCountTemplate: String!\n  schedulePollLaunchLabel: String!\n  schedulePollCancelLabel: String!\n  scheduleToastPollCreated: String!\n  scheduleToastVoted: String!\n  scheduleToastClosed: String!\n  scheduleToastFailedTemplate: String!\n  # 可用时间编辑面已归位个人设置: 排期页原位置只留这一行文字链\n  # 指向新落点 (客户端点击后打开设置 dialog 的可用时间页)。\n  scheduleSettingsLinkLabel: String!\n}\n\ntype AvailabilitySlot {\n  weekday: Int!      # 0 = 周日 (与 JS getDay 对齐)\n  startMinute: Int!  # UTC 当日分钟 0..1439\n  endMinute: Int!    # UTC 当日分钟, 可为 1440\n}\n\ninput AvailabilitySlotInput {\n  weekday: Int!\n  startMinute: Int!\n  endMinute: Int!\n}\n\ntype MemberAvailabilitySummary {\n  discordId: String!\n  displayName: String!\n  slots: [AvailabilitySlot!]!\n}\n\ntype TimePoll {\n  id: ID!\n  title: String!\n  status: String!  # open / closed\n  creatorDiscordId: String!\n  creatorName: String\n  createdAtText: String!\n  options: [TimePollOption!]!\n  # 本人已勾选的候选 id (未登录为 [])\n  myOptionIds: [ID!]!\n  # 关闭动作对象: 仅发起人或本百业管理员可见, 否则 null\n  closeActions: TimePollCloseActions\n  # 发车衔接: 仅发起人或本百业管理员可见; 客户端以所选候选时间\n  # 预填建车表单 (定档仍是人点选, 投票本身不建车)\n  launchActions: TimePollLaunchActions\n}\n\ntype TimePollOption {\n  id: ID!\n  startsAtUtc: Int!\n  startsAtText: String!  # 按观看者时区在服务端生成\n  voteCount: Int!\n  voterNames: [String!]!\n  votedByMe: Boolean!\n}\n\ntype TimePollCloseActions {\n  closeLabel: String!\n}\n\ntype TimePollLaunchActions {\n  launchLabel: String!\n}\n\ntype AvailabilityPayload {\n  ok: Boolean!\n  slots: [AvailabilitySlot!]!\n  error: String\n  errorCode: String\n}\n\ntype TimePollPayload {\n  ok: Boolean!\n  poll: TimePoll\n  error: String\n  errorCode: String\n}\n\ninput SetAvailabilityInput {\n  slug: String!\n  slots: [AvailabilitySlotInput!]!\n}\n\ninput CreateTimePollInput {\n  slug: String!\n  title: String!\n  candidateStartsAt: [String!]!\n}\n\ninput VoteTimePollInput {\n  pollId: ID!\n  optionIds: [ID!]!\n}\n\nextend type Mutation {\n  setMyAvailability(input: SetAvailabilityInput!): AvailabilityPayload!  # 存本人可用时段: 本百业可写成员, 只存本人\n  createTimePoll(input: CreateTimePollInput!): TimePollPayload!  # 发起时间投票: 本百业可写成员\n  voteTimePoll(input: VoteTimePollInput!): TimePollPayload!  # 多选可用式投票: 整组替换本人票\n  closeTimePoll(id: ID!): TimePollPayload!  # 关闭投票: 仅发起人或本百业管理员, 服务端复验\n}\n\n# ============ Mutations ============\n\ntype Mutation {\n  # 组队（无管理码，人人可管；唯一例外：编辑/解散/完成/恢复仅车头或本百业管理员可为）\n  createGrouping(input: CreateGroupingInput!): GroupingPayload!\n  updateGrouping(id: ID!, input: UpdateGroupingInput!): GroupingPayload!\n  disbandGrouping(id: ID!): DeletePayload!  # 解散车队：仅车头或本百业管理员可为，服务端复验\n  completeGrouping(id: ID!): GroupingPayload!  # 完成车队：仅车头或本百业管理员可为，服务端复验；完成车不进列表、不发提醒\n  reopenGrouping(id: ID!): GroupingPayload!  # 恢复车队（撤销完成，回到 open）：仅车头或本百业管理员可为，服务端复验\n  joinGrouping(input: JoinGroupingInput!): SeatPayload!\n  leaveGrouping(input: LeaveGroupingInput!): SeatPayload!\n  updateSeatWeapon(input: UpdateSeatWeaponInput!): SeatPayload!\n  setSeatReady(input: SetSeatReadyInput!): SeatPayload!  # 就位/取消就位: 仅本人身份戳座位, 服务端复验\n  createGroupingTemplate(input: CreateGroupingTemplateInput!): GroupingTemplatePayload!  # 存模板: 本百业可写成员\n  saveGroupingTemplate(input: SaveGroupingTemplateInput!): GroupingTemplatePayload!  # 把一辆现有车存为模板: 本百业可写成员\n  updateGroupingTemplate(id: ID!, input: GroupingTemplateInput!): GroupingTemplatePayload!  # 改模板: 仅创建者或本百业管理员, 服务端复验\n  deleteGroupingTemplate(id: ID!): DeletePayload!  # 删模板: 仅创建者或本百业管理员, 服务端复验\n\n  # 调律推演（服务端严格按 Excel 公式计算）\n  calcTiaolv(input: TiaolvInput!): TiaolvResult!\n\n  # 毕业率计算（6格平均，服务端计算）\n  calcGraduation(input: GraduationInput!): GraduationResult!\n}\n\n# 毕业率输入：8部位，每部位6格（1主+4副+1定音）\n# 口径：50%条数匹配 + 30%数值达成 + 20%三率达标（参考 gear-planner）\ninput GraduationInput {\n  sectSlug: String!  # 流派slug，用于获取目标配方\n  items: [GraduationItemInput!]!\n  precision: Float  # 三率：精准\n  crit: Float       # 三率：会心\n  affinity: Float    # 三率：会意\n}\n\ninput GraduationItemInput {\n  slot: String!  # 部位标识: GradPage.gradSlots 的 id (旧客户端可传规范名 主武器/副武器/…); 服务端不以此计算, 仅在结果中原样回显\n  affixes: [AffixValueInput!]!\n}\n\ninput AffixValueInput {\n  key: String!      # 词条key，如 max_atk\n  value: Float!     # 数值\n  resonance: Boolean! # 是否承音\n}\n\ntype GraduationResult {\n  total: Float!           # 总毕业率 0-100\n  countScore: Float!      # 条数匹配度 0-100\n  valueScore: Float!      # 数值达成度 0-100\n  rateScore: Float!       # 三率达标度 0-100\n  items: [GraduationItemResult!]!\n}\n\ntype GraduationItemResult {\n  slot: String!\n  score: Float!           # 单件 0-100\n}\n\ninput CreateGroupingInput {\n  slug: String!\n  title: String!\n  type: GroupingType!\n  startsAt: String!\n  dungeonId: ID\n  seats: [SeatInput!]\n  # 自定义报名表字段: 直接定义, 或由客户端从所选模板带入 (模板字段\n  # 在建车时被复制为本车自己的字段行, 之后与模板互不影响)\n  customFields: [CustomFieldInput!]\n}\n\ninput SeatInput {\n  nickname: String!\n  weapon: String!\n}\n\ninput UpdateGroupingInput {\n  title: String\n  startsAt: String\n  seats: [SeatInput!]\n}\n\ninput JoinGroupingInput {\n  groupingId: ID!\n  # 兼容保留: 落座名字一律由服务端定 (自己报名 = 本人 Discord 服务器\n  # 昵称回退全局名; 代报名 = 名册名), 客户端传值不作数。\n  nickname: String!\n  weapon: String!\n  seatIndex: Int!\n  # 代报名: 被代报成员的 Discord ID (必须在本百业名册内, 服务端复验);\n  # 缺省 = 为自己报名, 座位恒落本人身份戳。\n  forDiscordId: ID\n  # 自定义报名表答案 (按本车 customFields 的 fieldId 作答; 必填与\n  # 单选合法性由服务端按字段定义复验)\n  answers: [SignupAnswerInput!]\n}\n\ninput LeaveGroupingInput {\n  groupingId: ID!\n  uid: String!\n}\n\ninput UpdateSeatWeaponInput {\n  groupingId: ID!\n  uid: String!\n  weapon: String!\n}\n\n# 就位切换: 按调用者身份戳命中其在本车的全部座位 (一人多座同进退)\ninput SetSeatReadyInput {\n  groupingId: ID!\n  ready: Boolean!\n}\n\n# 调律推演输入 — 严格对应 片雲 DIY 0.10.2 Excel 可编辑区\n# 心法(F4:F7) 武学(F14) 武库(G9) 属性需求(H14) 套装(T2) 弓决(S2) 调律(K3:R5, K6:R24)\ninput TiaolvCellInput {\n  cell: String!   # Excel 单元格，如 \"K3\", \"R5\", \"K21\"（仅 K:R 用户调律区有效）\n  value: Float!\n}\n\ninput TiaolvInput {\n  innerSkills: [String!]!  # 4个心法名；\"N/A\" 表示空\n  wuxue: String            # 武学名，如 \"破竹鸢\"（Excel F14）\n  wuku: String             # 武库: TiaolvPage.tlWukuOptions 的 id (self/common); 旧客户端传规范名 \"本系\"/\"通用\" 亦可（Excel G9）\n  attrRequire: Float       # 属性需求数值（Excel H14，默认 492）\n  suit: String!            # 套装（Excel T2）: tlSuitOptions 的 id; 旧客户端传规范名如 \"撼天\" 亦可\n  bowSkill: String         # 弓决（Excel S2）: tlBowOptions 的 id (none = 不传/null); 旧客户端传规范名 会心/精准/会意 亦可\n  tunes: [TiaolvCellInput!]\n}\n\ntype GroupingPayload {\n  ok: Boolean!\n  grouping: Grouping\n  error: String      # 按请求 locale 由 errorCode 在服务端生成\n  errorCode: String  # 稳定错误码 (文案可变, 码不变)\n}\n\ntype SeatPayload {\n  ok: Boolean!\n  seats: [Seat!]\n  error: String\n  errorCode: String\n}\n\ntype DeletePayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n}\n\n# Excel 原术语：基础白值(B列) / 面板白值(C列) / 最终面板(D列)\ntype TiaolvRow {\n  key: String!      # 行键，如 minAtk\n  label: String!    # Excel 原标签，如 最小外攻\n  base: Float       # 基础白值\n  panel: Float      # 面板白值（无公式的行返回 null）\n  final: Float      # 最终面板\n}\n\ntype TiaolvResult {\n  rows: [TiaolvRow!]!\n}\n\n# ============ 百业公告 (沟通线 F9 / F10 / F18) ============\n# 一条管道三种能力: 管理员发布公告 (F9) 或紧急集合呼叫 (F18, 同一\n# 实体同一 mutation, 仅 kind 不同 — 紧急带服务端组合的紧急标记且\n# 走自己更严的每日频控), 全体成员经同一 Expo 推送管线收到推送,\n# 站内列表是全覆盖面 (无推送令牌者不漏); 成员打开公告即记已读\n# (F10), 作者/管理员在管理变体上看每条的已读/未读回执。\n# 频控走 usage counter 计量: 每百业每日普通公告 5 条 / 紧急呼叫\n# 2 次 (limits 服务的 FREE_LIMITS, 理由见 limits.ts)。\n\nenum AnnouncementKind {\n  STANDARD  # 普通公告 (F9)\n  URGENT    # 紧急集合呼叫 (F18)\n}\n\ntype GuildAnnouncement {\n  id: ID!\n  kind: AnnouncementKind!\n  urgent: Boolean!          # 紧急形态标记 (呈现区分; 与 kind 同源, 后端下发)\n  urgentLabel: String       # 紧急标记文案 (仅紧急公告下发, 其余为 null)\n  kindLabel: String!        # 类型文案 (公告 / 紧急集合, 后端按 locale 组合)\n  title: String!\n  body: String!\n  authorName: String!       # 发布者快照名 (发布时落库, 改名不影响历史)\n  authorText: String        # 「X 发布」组合文案 (无快照名为 null)\n  createdAtText: String!\n  viewerHasRead: Boolean    # 当前查看者本人已读态 (未登录为 null)\n  # Multilingual announcements (P26): display text served in the\n  # viewer's current locale — the translation when a current one\n  # exists, otherwise the original (identical to title/body). The\n  # original title/body always hold the as-published text.\n  displayTitle: String!\n  displayBody: String!\n  isTranslated: Boolean!    # whether the displayed text is a translation\n  contentSourceLabel: String!  # translated/original source label (server-composed by locale)\n  # Translation state (composed only on the admin variant while the\n  # multilingual entry is visible; otherwise always null)\n  translationStatusText: String\n  translations: [GuildAnnouncementTranslation!]\n  # 已读回执 (F10): 只在管理变体 (GuildAdmin.announcements) 的公告上\n  # 组合; 成员变体恒为 null — 回执名单不向普通成员下发。\n  readCount: Int\n  memberCount: Int\n  readCountText: String     # 「已读 x / y」组合文案 (管理变体)\n  receipts: [GuildAnnouncementReceipt!]\n  # 删除文案 (管理变体使用; 确认文案已在服务端按标题组合)\n  deleteLabel: String!\n  deleteConfirmTitle: String!\n  deleteConfirmMessage: String!\n}\n\n# Multilingual announcements (P26): one target locale's translation\n# state, served with the announcement only on the admin variant\n# while the entry is visible. status: PENDING / DONE / FAILED.\ntype GuildAnnouncementTranslation {\n  locale: String!\n  localeLabel: String!      # language name (server-composed in the viewer's locale)\n  status: String!\n  statusLabel: String!      # status copy (server-composed)\n}\n\ntype GuildAnnouncementReceipt {\n  discordId: ID!\n  displayName: String!      # 名册口径: 昵称回退全局名\n  read: Boolean!\n  readAtText: String        # 已读时刻 (未读为 null)\n}\n\ntype GuildAnnouncementPage {\n  # 文案 (announcements 目录, 后端按请求 locale 生成; 前端零字符串)\n  title: String!\n  emptyText: String!\n  urgentLabel: String!\n  composeTitle: String!\n  kindLabel: String!\n  kindStandardLabel: String!\n  kindUrgentLabel: String!\n  titleLabel: String!\n  titlePlaceholder: String!\n  bodyLabel: String!\n  bodyPlaceholder: String!\n  postLabel: String!\n  postingLabel: String!\n  postedText: String!\n  deleteLabel: String!\n  receiptsTitle: String!\n  readListLabel: String!\n  unreadListLabel: String!\n  pushNote: String!\n  urgentNote: String!\n  dailyLimitText: String    # 「今日还可发布 x 条」 (仅管理变体组合)\n  # 发布能力只存在于管理变体: 成员变体 canPost 恒 false、余量恒 null,\n  # 发布表单只在 canPost 时挂载; mutation 端独立复验管理判定。\n  canPost: Boolean!\n  standardRemaining: Int\n  urgentRemaining: Int\n  announcements: [GuildAnnouncement!]!\n  # Multilingual entry (P26, admin variant only): entry copy is\n  # served only when the guild's tier reaches T2 — a pure\n  # entitlement verdict that never consults the paygate master\n  # switch; below T2 everything here is\n  # null/false and the surface is identical to before P26. When the\n  # entry is visible but the translation provider is not\n  # configured, canGenerateTranslations is false and\n  # translationUnavailableText carries the not-enabled note.\n  canGenerateTranslations: Boolean!\n  generateTranslationsLabel: String\n  generatingTranslationsLabel: String\n  translationsGeneratedText: String\n  translationsPartialText: String\n  translationUnavailableText: String\n}\n\ntype GuildAnnouncementPayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n  announcement: GuildAnnouncement\n}\n\nextend type Mutation {\n  # 发布公告/紧急呼叫: 管理判定 (所绑服务器管理员, 含 omni) 复验;\n  # 错误码 announcementTitleRequired / announcementTitleTooLong /\n  # announcementBodyTooLong / announcementDailyLimit /\n  # urgentCallDailyLimit / adminOnly / guildNotFound (文案走 errors 目录)\n  postGuildAnnouncement(slug: String!, kind: AnnouncementKind!, title: String!, body: String!): GuildAnnouncementPayload!\n  # 标已读: 登录成员本人, 公告按本百业解析 (跨百业 id 视为不存在);\n  # 错误码 loginRequired / memberOnly / announcementNotFound / guildNotFound\n  markGuildAnnouncementRead(slug: String!, announcementId: ID!): GuildAnnouncementPayload!\n  # 删除公告 (连带其已读回执): 管理判定复验, 按本百业解析\n  deleteGuildAnnouncement(slug: String!, announcementId: ID!): GuildAnnouncementPayload!\n  # Generate the multilingual versions (P26): manual trigger\n  # (translation is metered; posting never auto-translates); the\n  # admin verdict is re-checked, plus the tier-at-T2 verdict;\n  # provider not configured -> translationNotConfigured; a single\n  # locale's failure is recorded as a failed state and never\n  # affects the original or this response (ok stays true, state is\n  # served on the announcement's translation fields)\n  generateGuildAnnouncementTranslations(slug: String!, announcementId: ID!): GuildAnnouncementPayload!\n}\n\n# ============ 军官工具 (免费功能线 F12/F11/F19, 不挂权益门) ============\n# F12 成员备注只存在于 GuildOfficerPage (挂 GuildAdmin): 成员变体\n# 根本不带备注字段 — 不是前端隐藏, 是响应类型不下发。F19 赛季目标\n# 的写面只认调用者本人 (仓储按 owner 钉行), 军官侧只有只读总览。\n\nenum SeasonGoalStatus {\n  ACTIVE\n  DONE\n  DROPPED\n}\n\ntype GuildMemberNote {\n  id: ID!\n  body: String!\n  authorName: String!       # 备注作者快照名 (写入时落库)\n  authorText: String        # 「X 添加」组合文案 (无快照名为 null)\n  createdAtText: String!\n  updatedAtText: String!\n}\n\ntype MemberSeasonGoal {\n  id: ID!\n  guildSlug: String!\n  guildName: String!\n  title: String!\n  note: String!             # 成员自维护的进度备注\n  status: SeasonGoalStatus!\n  statusLabel: String!      # 状态文案 (后端按 locale 组合)\n  dungeonId: Int            # 可选关联副本 (dex 副本行 id; 纯文本目标为 null)\n  dungeonName: String       # 关联副本名 (后端数据, 非前端字典)\n  seasonName: String        # 关联副本所属赛季名 (后端赛季表)\n  createdAtText: String!\n  updatedAtText: String!\n}\n\ntype GuildOfficerMember {\n  discordId: ID!\n  displayName: String!      # 名册口径: 昵称回退全局名\n  notes: [GuildMemberNote!]!\n  goals: [MemberSeasonGoal!]!\n}\n\ntype GuildOfficerPage {\n  # 文案 (officer 目录, 后端按请求 locale 生成; 前端零字符串)\n  notesTitle: String!\n  notesHint: String!\n  notesEmptyText: String!\n  memberNoNotesText: String!\n  notePlaceholder: String!\n  noteAddLabel: String!\n  noteEditLabel: String!\n  noteSaveLabel: String!\n  noteDeleteLabel: String!\n  exportTitle: String!\n  exportHint: String!\n  exportLabel: String!\n  goalsTitle: String!\n  goalsHint: String!\n  goalsEmptyText: String!\n  # 名册为中心: 每位成员挂自己的备注 (F12) 与赛季目标 (F19 只读\n  # 总览); hasGoals 决定目标区空态文案是否出现 (组合结论, 非权限)。\n  members: [GuildOfficerMember!]!\n  hasGoals: Boolean!\n}\n\ntype MySeasonGoalPage {\n  # 文案 (officer 目录, 后端按请求 locale 生成; 前端零字符串)\n  entryLabel: String!\n  title: String!\n  hint: String!\n  emptyText: String!\n  guildLabel: String!\n  goalTitleLabel: String!\n  goalTitlePlaceholder: String!\n  goalNoteLabel: String!\n  goalNotePlaceholder: String!\n  dungeonLabel: String!\n  dungeonNoneLabel: String!\n  statusLabel: String!\n  addLabel: String!\n  saveLabel: String!\n  editLabel: String!\n  deleteLabel: String!\n  statusActiveLabel: String!\n  statusDoneLabel: String!\n  statusDroppedLabel: String!\n  # 我在各百业的目标 (跨百业汇总, 每条带所属百业名); 可建目标的\n  # 百业 = 我的名册行; 副本选项来自 dex 数据 (含其赛季名)。\n  goals: [MemberSeasonGoal!]!\n  guildOptions: [SeasonGoalGuildOption!]!\n  dungeonOptions: [SeasonGoalDungeonOption!]!\n}\n\ntype SeasonGoalGuildOption {\n  slug: String!\n  name: String!\n}\n\ntype SeasonGoalDungeonOption {\n  id: Int!\n  name: String!\n  seasonName: String\n}\n\ntype GuildMemberNotePayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n  note: GuildMemberNote\n}\n\ntype GuildExportPayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n  json: String              # 数据包文档 (guild-export v1, JSON)\n  filename: String\n}\n\ntype SeasonGoalPayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n  goal: MemberSeasonGoal\n}\n\ninput SeasonGoalInput {\n  id: ID                    # null = 新建; 给出 = 改自己的既有目标\n  slug: String!\n  title: String!\n  note: String\n  status: SeasonGoalStatus\n  dungeonId: Int            # null = 不关联副本\n}\n\nextend type Mutation {\n  # F12 写备注: 管理判定复验; 目标必须是本百业名册成员;\n  # 错误码 officerMemberNotFound / officerNoteBodyRequired /\n  # officerNoteBodyTooLong / adminOnly / guildNotFound\n  addGuildMemberNote(slug: String!, memberDiscordId: ID!, body: String!): GuildMemberNotePayload!\n  # F12 改备注: 管理判定复验, 备注按本百业解析 (跨百业 id 视为不存在)\n  updateGuildMemberNote(slug: String!, noteId: ID!, body: String!): GuildMemberNotePayload!\n  # F12 删备注: 管理判定复验, 按本百业解析\n  deleteGuildMemberNote(slug: String!, noteId: ID!): GuildMemberNotePayload!\n  # F11 导出本百业数据包: 管理判定复验, 只导本百业; 动作在\n  # hub_audit_log 留痕 (actor + tenant + 计数摘要)\n  exportGuildDataPackage(slug: String!): GuildExportPayload!\n  # F19 建/改自己的赛季目标: 成员写门 + 目标归属调用者本人;\n  # 错误码 seasonGoalTitleRequired / seasonGoalTitleTooLong /\n  # seasonGoalNoteTooLong / seasonGoalNotFound /\n  # seasonGoalDungeonNotFound / loginRequired / memberOnly / guildNotFound\n  upsertMySeasonGoal(input: SeasonGoalInput!): SeasonGoalPayload!\n  # F19 删自己的赛季目标: 归属调用者本人 (他人 id 视为不存在)\n  deleteMySeasonGoal(goalId: ID!): SeasonGoalPayload!\n}\n\n# ============ 登录 / Viewer 层级 (root = user) ============\n# 结构: Query.viewer -> guilds / guild(slug) -> groupings 等页面数据\n# 权限不用状态标志表达 (flag 可 forge), 用「响应的类型」表达:\n#   成员        -> Guild        (完整数据, 写入口只存在于该类型的组件里)\n#   未绑定百业  -> GuildReadOnly(公开只读数据, 无写入口)\n#   非成员/不存在 -> GuildLocked (不携带任何百业内容数据)\n# 前端按 __typename 分发组件; 没数据 = 没能力。mutation 在 resolver 内独立复验。\n\ntype DiscordUser {\n  discordId: String!\n  name: String!\n  avatar: String\n}\n\n# 当前用户有管理权限 (Administrator/ManageGuild/服主) 的 Discord 服务器。\n# 服务端已过滤: 下发的每一台都可用于建业/绑定, 不下发权限位给前端判断。\ntype DiscordServer {\n  id: String!\n  name: String!\n  icon: String\n}\n\n# 百业成员名册条目 (代报名选人用): 名字口径与服务端落座一致\n# (名册昵称, 回退全局名); globalName 供选择器在昵称重名时消歧。\ntype GuildRosterMember {\n  discordId: ID!\n  displayName: String!\n  globalName: String\n}\n\n# 已绑定服务器 + 当前用户是成员: 完整数据\ntype Guild {\n  slug: String!\n  name: String\n  slogan: String\n  gameVersion: String!\n  memberCount: Int!\n  # 百业自定义头像 (管理员上传) 的版本化公开 URL; 无头像为 null。\n  # 公开品牌图, Guild / GuildReadOnly 两面都下发 (Locked 不带内容数据)。\n  avatarUrl: String\n  groupings(tab: GroupingTab!): GroupingListPage!\n  viewerNick: String\n  # 成员名册: 仅完整 Guild 面声明 — GuildReadOnly / GuildLocked 无此\n  # 字段, 权限由响应类型本身表达 (不下发任何权限标志位)。\n  memberRoster: [GuildRosterMember!]!\n  # 百业公告 (沟通线 F9/F10/F18): 成员变体 — 公告列表 + 本人已读态;\n  # 发布与已读回执名单只在管理变体 (GuildAdmin.announcements)。\n  announcements: GuildAnnouncementPage!\n  # 百业主页外壳文案 (shell gen 方法按请求 locale 生成)\n  homeBackToHubLabel: String!\n  homeTabTeamLabel: String!\n  homeTabDexLabel: String!\n  homeTabSectLabel: String!\n  homeTabAnnouncementsLabel: String!\n  homeTabScheduleLabel: String!\n  homeTabMarketLabel: String!\n  homeTabAlliesLabel: String!\n  # 管理入口文案: 仅通过管理判定 (getGuildAdminAccess, 与管理面同一\n  # 口径, 含 omni) 的查看者才下发; 其余成员为 null, 主页不渲染入口 —\n  # 进不去的入口不广告。可空即为此意, 勿改回 String!。\n  homeAdminLabel: String\n  detailNotFoundText: String!\n  detailBackToListLabel: String!\n  # 白标 chrome 组合 (Premium 第一梯队, 不挂 gate): 服务端按本百业的\n  # 白标设置组合 — 品牌可见时返回标签带平台名、页脚声明为平台声明;\n  # 隐藏品牌时返回标签为素文案、页脚声明为 null (客户端照单渲染,\n  # 无任何品牌判断分支, 与 homeAdminLabel 同一组合哲学)。\n  pageBackLabel: String!\n  pageFooterDisclaimerText: String\n}\n\n# 未绑定 Discord 服务器: 公开可读, 写功能锁死 (该类型不含任何写入口)\ntype GuildReadOnly {\n  slug: String!\n  name: String\n  slogan: String\n  gameVersion: String!\n  memberCount: Int!\n  avatarUrl: String\n  groupings(tab: GroupingTab!): GroupingListPage!\n  viewerNick: String\n  announcements: GuildAnnouncementPage!\n  # 百业主页外壳文案 (shell gen 方法按请求 locale 生成)\n  homeBackToHubLabel: String!\n  homeTabTeamLabel: String!\n  homeTabDexLabel: String!\n  homeTabSectLabel: String!\n  homeTabAnnouncementsLabel: String!\n  homeTabScheduleLabel: String!\n  homeTabMarketLabel: String!\n  homeTabAlliesLabel: String!\n  homeReadOnlyBanner: String!\n  detailNotFoundText: String!\n  detailBackToListLabel: String!\n  # 白标 chrome 组合: 与 Guild 同口径 (见上)。\n  pageBackLabel: String!\n  pageFooterDisclaimerText: String\n}\n\n# 已绑定但非成员 / 百业不存在: 不携带任何百业内容数据 (仅 slug 与本页文案)\ntype GuildLocked {\n  slug: String!\n  lockedBackLinkLabel: String!\n  lockedTitle: String!\n  lockedBody1: String!\n  lockedBody2: String!\n  lockedBackButtonLabel: String!\n}\n\nunion GuildResult = Guild | GuildReadOnly | GuildLocked\n\ntype Viewer {\n  user: DiscordUser             # 未登录为 null\n  guilds: [Guild!]!             # 我可用的百业 (成员; 服务端过滤, 前端不许拉全量再筛)\n  publicGuilds: [GuildReadOnly!]!  # 未绑定服务器的公开百业 (只读)\n  guild(slug: String!): GuildResult!\n  guildAdmin(slug: String!): GuildAdminResult!  # 百业管理面: 响应类型即权限结论 (见下方 GuildAdmin)\n  homeRecruit: HomeRecruitSection!  # 平台主页招新区 (F16 申请 / F24 清单 / F17 我的配对): 组成即权限结论 (见下方 HomeRecruitSection)\n  fillMarket(slug: String!): FillMarketResult!  # 补位市场页 (P19): 成员页 / Locked, 需求区按 T3 再分型 (见下方 FillMarketPage)\n  guildAllies(slug: String!): GuildAlliesResult!  # 盟友百业页 (P20): 成员页 / Locked, 结盟与共享均为读时判定\n  discordServers: [DiscordServer!]!  # 我有管理权限的服务器 (服务端过滤)\n  # UI 文案: 站点/登录/选择页/创建页/通用 — 全部由 Viewer shell 的 gen\n  # 方法按请求 locale 生成, 未选中永不生成 (无 Strings 类型, 文案字段\n  # 直接长在 shell 类型上)。\n  siteTitle: String!\n  siteSubtitle: String!\n  siteHeroAlt: String!\n  siteSealText: String!  # 品牌印章字形 (无头像百业的占位印文, 后端下发)\n  loginCardTitle: String!\n  loginCardBody1: String!\n  loginCardBody2: String!\n  loginButtonLabel: String!\n  loginPrivacyText: String!\n  # 匿名落地页功能区文案 (根路径匿名态呈现; 登录卡沿用上面的 login* 字段)\n  landingFeaturesTitle: String!\n  landingGroupingTitle: String!\n  landingGroupingBody: String!\n  landingReminderTitle: String!\n  landingReminderBody: String!\n  landingDexTitle: String!\n  landingDexBody: String!\n  landingGearTitle: String!\n  landingGearBody: String!\n  # 全站页脚: 非官方声明正文 + 服务条款/隐私政策入口文案 (后端生成)\n  footerDisclaimerText: String!\n  footerTermsLabel: String!\n  footerPrivacyLabel: String!\n  userBarLogoutLabel: String!\n  userBarLoggingOutLabel: String!\n  userBarSettingsLabel: String!\n  # 账号级语言偏好 (null = 自动跟随浏览器) 与本请求实际生效 locale\n  myLocalePref: String\n  myEffectiveLocale: String!\n  pickerMyGuildsLabel: String!\n  pickerMyGuildsEnLabel: String!\n  pickerPublicGuildsLabel: String!\n  pickerPublicGuildsEnLabel: String!\n  pickerReadOnlyBadge: String!\n  pickerEmptyTitle: String!\n  pickerEmptyBody: String!\n  pickerCreateGuildLabel: String!\n  pickerCreateGuildMoreLabel: String!\n  createBackLinkLabel: String!\n  createTitle: String!\n  createSubtitle: String!\n  createNameLabel: String!\n  createNamePlaceholder: String!\n  createSlugLabel: String!\n  createSlugPlaceholder: String!\n  createSlugCheckingText: String!\n  createSlugTakenText: String!\n  createSlugNote: String!\n  createServerLabel: String!\n  createNoServers1: String!\n  createNoServers2: String!\n  createSubmitLabel: String!\n  createSubmittingLabel: String!\n  createToastNameShort: String!\n  createToastSlugRequired: String!\n  createToastSlugBad: String!\n  createToastServerRequired: String!\n  createToastCreated: String!\n  createToastFailed: String!\n  slugAvailableMessage(slug: String!): String!\n  commonCancelLabel: String!\n  commonConfirmLabel: String!\n  commonUnknownErrorText: String!\n  commonRenderErrorTemplate: String!\n  commonRenderErrorHint: String!\n  commonBackToHubLabel: String!\n  commonLoadingGuildText: String!\n}\n\nextend type Query {\n  viewer: Viewer!\n  slugAvailable(slug: String!): Boolean!\n}\n\ninput CreateGuildInput {\n  name: String!\n  slug: String!\n  discordGuildId: String!  # 必须是当前用户有管理权限的 Discord 服务器 (服务端复验)\n}\n\ntype CreateGuildPayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n  guild: Guild\n}\n\n\nextend type Mutation {\n  createGuild(input: CreateGuildInput!): CreateGuildPayload!\n}\n\n# ============ 百业管理面 (原 gadmin, 2026-10-26 迁 GraphQL) ============\n# 入口 Viewer.guildAdmin(slug): 鉴权 = Discord 会话 + 查看者是该百业\n# 所绑 Discord 服务器的管理员 (与 createGuild 同一校验: 服务器主或\n# Administrator / ManageGuild 位)。权限只由响应类型表达: GuildAdmin\n# 携带全部管理数据与文案; GuildAdminLocked 只带 slug 与本页文案, 不带\n# 任何百业数据。所有 admin 变更在 resolver 内复验同一结论, 不信前端。\n# 原 gadmin 的百业密码登录随迁移废弃 (Discord 会话是唯一身份)。\n# 提醒 Webhook 是密钥: 只下发是否已设置 + Webhook 数字编号 (可辨认\n# 频道, 不可用于发帖), 完整 URL 永不回读 (与超管门户保存后掩码同规)。\n\nunion GuildAdminResult = GuildAdmin | GuildAdminLocked\n\ntype GuildAdminLocked {\n  slug: String!\n  adminLockedTitle: String!\n  adminLockedBody: String!\n  adminBackLinkLabel: String!\n}\n\ntype GuildAdmin {\n  slug: String!\n  name: String\n  announcement: String!\n  slogan: String\n  masterName: String!\n  logoUrl: String!\n  bgImageUrl: String!\n  avatarUrl: String\n  avatarUpdatedAt: String\n  discordGuildId: String!\n  reminderWebhookSet: Boolean!\n  reminderWebhookId: String\n  reminderOffsets: [Int!]!  # 发车提醒提前量 (分钟, 管理员多选; 默认 [10])\n  reminderCustomText: String!  # 发车提醒自定义文案 (一行, 空 = 不显示)\n  # 白标进阶 (Premium 第一梯队, 不挂 gate): 只挂 GuildAdmin — Locked\n  # 零设置字段。强调色只能从 ogAccentOptions 的服务端色板里选 key,\n  # 不接受自由色值; 标题后缀一行文本 (空 = 无后缀)。\n  whiteLabelHideBranding: Boolean!\n  ogAccent: String!  # 当前强调色 key (空 = 未定制)\n  ogTitleSuffix: String!\n  ogAccentOptions: [GuildAdminOgAccentOption!]!\n  # 平台子域 (白标档 A) 不在此挂任何字段: 开关归平台 (hub 操作面),\n  # 能力先建后藏, Premium 正式推出前对百业侧完全不可见。\n  # 本百业页面的有效页脚声明 (白标组合, 与成员面 Guild 同口径):\n  # 隐藏品牌时为 null, 管理页所在的站点外壳据此不渲染页脚。\n  pageFooterDisclaimerText: String\n  devOnly: Boolean!\n  gameVersion: String!\n  events: [GuildAdminEvent!]!\n  schoolGuides: GuildAdminSchoolGuides!\n  # 公告广播 (F9/F10/F18) 管理变体: 发布表单 + 每日余量 + 已读回执;\n  # 只挂 GuildAdmin — Locked 零公告字段。\n  announcements: GuildAnnouncementPage!\n  # 军官工具 (免费功能线 F12/F11/F19, 不挂任何权益门): 成员备注 +\n  # 数据包导出 + 成员赛季目标总览; 只挂 GuildAdmin — Locked 零工具\n  # 字段, 成员变体 (Guild / GuildReadOnly) 根本不带备注字段。\n  officer: GuildOfficerPage!\n  ops: GuildAdminOpsResult!\n  # 出勤统计 (Premium, 读侧门控): 总闸开且本百业未开通时组合为\n  # GuildAdminStatsLocked (只有未开通文案, 零统计数据); 总闸关或\n  # 已开通时与从前一致。结论只由响应类型表达, 无标志位下发。\n  stats: GuildAdminStatsResult!\n  # Premium 权益面: 总闸关时为 null (管理面与从前逐字一致, 该面\n  # 不出现); 总闸开时按权益组合 Active / Locked 变体 — Locked 带\n  # 价格位与开通入口 (Stripe 未配置时价格位为 null、改由即将开放\n  # 文案占据), Active 带方案来源与当前周期。\n  premium: GuildAdminPremiumResult\n  # 活动工具 (免费功能, 不挂任何权益门): 活动日历订阅 (F8) + 活动\n  # 抽奖 (F21), 只挂 GuildAdmin — Locked 零工具字段。日历订阅链在\n  # 抽奖的名单在创建时定格 (来源: 某辆车的参与者, 或手选本百业\n  # 成员), 开奖不重复中奖, 抽奖/名单/权重/结果全部留痕, 由\n  # lotteries 字段回读。\n  lotteries: [GuildAdminLottery!]!\n  lotteryRoster: [GuildAdminLotteryMember!]!\n  # 赛季前检查清单 (免费功能, 不挂 gate): 条目由后端按当前版本/赛季\n  # 数据组合下发, 勾选状态按百业 + 赛季持久化; 只挂 GuildAdmin。\n  seasonChecklist: GuildSeasonChecklist!\n  # 成员名册 (免费功能, 不挂 gate): 游戏内名字名册, 与 Discord 成员\n  # 资格 (guild_members) 正交; 截图 OCR 导入经待确认预览才落库。\n  roster: GuildRoster!\n  # 招新新人线 (免费功能, 不挂任何权益门): 招新开关、入业申请审核\n  # 队列 (F16)、导师人选与配对 (F17)、新人清单进度总览 (F24); 只挂\n  # GuildAdmin — Locked 零招新字段。审核/配对写操作全部走下方\n  # mutation 并在 resolver 内复验管理结论。通过申请的平台侧效果 =\n  # 申请结案 + 登记进本百业名册; Discord 服务器成员身份平台无写\n  # 通道 (无 bot 令牌, OAuth 为用户只读授权), 申请人通过后自行\n  # 加入绑定服务器 —— 主页招新区的 approvedNextStep 文案逐字\n  # 说明这一步。\n  # 招新开关 (tenants.recruit_open, 默认关): 开启的百业才进平台\n  # 主页招新目录并接受入业申请; 成员的新人拼装不看此开关。\n  recruitOpen: Boolean!\n  recruitApplications: [RecruitApplication!]!\n  recruitPairings: [MentorPairing!]!\n  recruitRoster: [RecruitMember!]!\n  newcomerProgress: [NewcomerProgress!]!\n  # 管理页文案 (guildAdmin 目录, 按请求 locale 生成)\n  adminTitle: String!\n  adminBackLinkLabel: String!\n  adminTabProfileLabel: String!\n  adminTabDiscordLabel: String!\n  adminTabEventsLabel: String!\n  adminTabGuidesLabel: String!\n  adminTabAnnouncementsLabel: String!\n  adminSaveLabel: String!\n  adminSavedText: String!\n  adminDeleteLabel: String!\n  adminEditLabel: String!\n  adminAddLabel: String!\n  adminProfileTitle: String!\n  adminNameLabel: String!\n  adminAnnouncementLabel: String!\n  adminSloganLabel: String!\n  adminMasterNameLabel: String!\n  adminLogoUrlLabel: String!\n  adminBgImageUrlLabel: String!\n  adminAvatarTitle: String!\n  adminAvatarUploadLabel: String!\n  adminAvatarReplaceLabel: String!\n  adminAvatarDeleteLabel: String!\n  adminAvatarNoneText: String!\n  adminAvatarHint: String!\n  adminDiscordTitle: String!\n  adminWebhookLabel: String!\n  adminWebhookSetText: String!\n  adminWebhookUnsetText: String!\n  adminWebhookHint: String!\n  adminWebhookClearLabel: String!\n  adminGuildIdLabel: String!\n  adminGuildIdUnboundText: String!\n  adminReminderTitle: String!\n  adminReminderOffsetsLabel: String!\n  adminReminderOffsetTemplate: String!\n  adminReminderCustomTextLabel: String!\n  adminReminderCustomTextHint: String!\n  adminVisibilityTitle: String!\n  adminDevOnlyLabel: String!\n  adminEventsTitle: String!\n  adminSignupCsvSuffix: String!\n  adminEventEmptyText: String!\n  adminEventTitleLabel: String!\n  adminEventTypeLabel: String!\n  adminEventStatusLabel: String!\n  adminEventTimeLabel: String!\n  adminEventSlotsLabel: String!\n  adminEventMeetLabel: String!\n  adminEventDescLabel: String!\n  adminEventDungeonLabel: String!\n  adminTypeActivityText: String!\n  adminTypeTalentText: String!\n  adminTypeRaceText: String!\n  adminTypeTowerText: String!\n  adminStatusOpenText: String!\n  adminStatusClosedText: String!\n  adminStatusCompletedText: String!\n  adminStatusDraftText: String!\n  adminSignupsTitle: String!\n  adminSignupEmptyText: String!\n  adminExportCsvLabel: String!\n  adminRemoveSignupLabel: String!\n  adminResultsTitle: String!\n  adminResultTeamLabel: String!\n  adminResultMembersLabel: String!\n  adminResultTimeLabel: String!\n  adminResultProofLabel: String!\n  adminResultNoteLabel: String!\n  adminGuidesTitle: String!\n  adminGuidesHint: String!\n  adminGuideSchoolLabel: String!\n  adminGuideBuildLabel: String!\n  adminGuideAttrLabel: String!\n  adminGuideRateLabel: String!\n  adminGuideBisLabel: String!\n  adminGuideRotationLabel: String!\n  adminTabStatsLabel: String!\n  adminTabSeasonLabel: String!\n  adminStatsTitle: String!\n  adminStatsCurrentWeekLabel: String!\n  adminStatsCarsLabel: String!\n  adminStatsCompletedLabel: String!\n  adminStatsSeatsLabel: String!\n  adminStatsFillRateLabel: String!\n  adminStatsParticipantsLabel: String!\n  adminStatsPerCapitaLabel: String!\n  adminStatsMembersTitle: String!\n  adminStatsLeadersTitle: String!\n  adminStatsSeatCountLabel: String!\n  adminStatsCarCountLabel: String!\n  adminStatsEmptyText: String!\n  adminStatsBoardEmptyText: String!\n  adminWhiteLabelTitle: String!\n  adminHideBrandingLabel: String!\n  adminHideBrandingHint: String!\n  adminOgAccentLabel: String!\n  adminOgTitleSuffixLabel: String!\n  adminOgTitleSuffixHint: String!\n  adminBillingSuccessText: String!\n  adminBillingCanceledText: String!\n  adminPremiumTitle: String!\n  adminTabToolsLabel: String!\n  adminTabOfficerLabel: String!\n  adminTabOpsLabel: String!\n  adminLotteryTitle: String!\n  adminLotteryHint: String!\n  adminLotteryEmptyText: String!\n  adminLotteryNameLabel: String!\n  adminLotteryPrizeLabel: String!\n  adminLotterySourceLabel: String!\n  adminLotterySourceGroupingText: String!\n  adminLotterySourceMembersText: String!\n  adminLotteryGroupingLabel: String!\n  adminLotteryWinnerCountLabel: String!\n  adminLotteryUniformWeightLabel: String!\n  adminLotteryWeightLabel: String!\n  adminLotteryEntriesLabel: String!\n  adminLotteryWinnersLabel: String!\n  adminLotteryCreateLabel: String!\n  adminLotteryDrawLabel: String!\n  adminLotteryStatusOpenText: String!\n  adminLotteryStatusDrawnText: String!\n  adminTabRecruitLabel: String!\n  adminRecruitApplicationsTitle: String!\n  adminRecruitApplicationsEmptyText: String!\n  adminRecruitApproveLabel: String!\n  adminRecruitRejectLabel: String!\n  adminRecruitMentorPoolTitle: String!\n  adminRecruitSetMentorLabel: String!\n  adminRecruitUnsetMentorLabel: String!\n  adminRecruitPairingsTitle: String!\n  adminRecruitPairingsEmptyText: String!\n  adminRecruitPairingCreateLabel: String!\n  adminRecruitPairingEndLabel: String!\n  adminRecruitMentorSelectLabel: String!\n  adminRecruitMenteeSelectLabel: String!\n  adminRecruitNewcomersTitle: String!\n  adminRecruitNewcomersEmptyText: String!\n  adminRecruitOpenLabel: String!\n  adminRecruitOpenHint: String!\n  adminRecruitProfileLabel: String!\n  adminRecruitMentorLabel: String!\n  adminRecruitFirstRunLabel: String!\n}\n\n# 抽奖参与名单来源: GROUPING = 某辆车的已落座参与者快照;\n# MEMBERS = 管理员从本百业名册手选。\nenum LotterySource {\n  GROUPING\n  MEMBERS\n}\n\nenum LotteryStatus {\n  OPEN\n  DRAWN\n}\n\n# 一次抽奖的留痕全貌: 奖池 (prize)、名单来源、定格名单 (含权重)、\n# 中奖结果与时间都在本类型回读。\ntype GuildAdminLottery {\n  id: ID!\n  title: String!\n  prize: String!\n  source: LotterySource!\n  sourceEventId: ID\n  sourceEventTitle: String\n  winnerCount: Int!\n  status: LotteryStatus!\n  entryCountText: String!\n  createdAtText: String!\n  drawnAtText: String\n  entries: [GuildAdminLotteryEntry!]!\n  winners: [GuildAdminLotteryEntry!]!\n}\n\ntype GuildAdminLotteryEntry {\n  discordId: String!\n  displayName: String!\n  weight: Int!\n}\n\n# 手选名单的候选行: 本百业名册 (guild_members) 的成员。\n# ============ 招新新人线 (F16 / F24 / F17, 免费功能) ============\n# 申请状态: PENDING 待审核 -> APPROVED 已通过 / REJECTED 未通过;\n# 结案后不可改判 (仓储层 still-pending 守卫), 未通过者可重新申请。\nenum RecruitApplicationStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nenum MentorPairingStatus {\n  ACTIVE\n  ENDED\n}\n\n# 一份入业申请的留痕全貌: 附言、状态、申请与审核时间、审核人。\n# 申请人本人在招新页读自己的 (最新一份), 管理员在审核队列读全量。\ntype RecruitApplication {\n  id: ID!\n  applicantDiscordId: String!\n  applicantName: String!\n  message: String!\n  status: RecruitApplicationStatus!\n  statusLabel: String!\n  createdAtText: String!\n  reviewedByName: String\n  reviewedAtText: String\n}\n\n# 一段导师配对: 双方名快照 + 状态 + 建立/结束时间, 全部留痕。\ntype MentorPairing {\n  id: ID!\n  mentorDiscordId: String!\n  mentorName: String!\n  menteeDiscordId: String!\n  menteeName: String!\n  status: MentorPairingStatus!\n  statusLabel: String!\n  createdAtText: String!\n  endedAtText: String\n}\n\n# 名册行 + 导师人选标记: 管理面据此设导师、建配对 (标记只是数据,\n# 写操作仍在 resolver 内复验人选资格, 前端不据标记自行放行)。\ntype RecruitMember {\n  discordId: String!\n  displayName: String!\n  isMentor: Boolean!\n}\n\ntype NewcomerChecklistItem {\n  key: String!\n  label: String!\n  hint: String!\n  done: Boolean!\n}\n\n# 新人入业清单 (F24): 四项全部从既有数据推导, 平台不存清单状态 —\n# profile = 本百业有落座且流派非空的座位 (时区由客户端每请求呈现,\n# 平台无存储型时区资料, 故该半项无需填写、永不阻塞); availability =\n# 本人已在本百业填写可用时间 (个人设置中的编辑面, 可跳过、永不\n# 阻塞); mentor = 本人为一段进行中配对的新人; firstRun = 在已完\n# 成的车队中落座。\ntype NewcomerChecklist {\n  items: [NewcomerChecklistItem!]!\n  doneCount: Int!\n  totalCount: Int!\n  progressText: String!\n}\n\n# 军官侧新人总览行: 清单四项结论逐项下发 (与本人视图同一推导)。\ntype NewcomerProgress {\n  discordId: String!\n  displayName: String!\n  profileDone: Boolean!\n  availabilityDone: Boolean!\n  mentorDone: Boolean!\n  firstRunDone: Boolean!\n  doneCount: Int!\n  progressText: String!\n}\n\n# 平台主页招新区 (招新线 F16/F24/F17 的唯一会员面; 独立招新页已解\n# 散): 目录对所有人公开, 只列已绑定服务器且开启招新\n# (tenants.recruit_open) 的百业 (名称/简介/头像为平台公开口径, 与\n# GuildCard 同集); 申请区只为登录非成员按百业拼装; 新人拼装只为\n# 成员 (清单) 与被配对者 (配对) 拼装, 不看招新开关。匿名两区皆\n# 空 — 组成即结论, 无任何权限标志位。文案全部后端下发。主页只\n# 渲染摘要行, 细节 (申请区全文 / 清单四项 / 配对) 由前端在\n# dialog (web) / 推页 (mobile) 里呈现同一份下发数据。\ntype HomeRecruitSection {\n  recruitTitle: String!\n  homeBody: String!\n  homeLoginHint: String!\n  applySectionTitle: String!\n  messageLabel: String!\n  messagePlaceholder: String!\n  submitLabel: String!\n  submittingLabel: String!\n  myApplicationTitle: String!\n  pendingHint: String!\n  approvedNextStepText: String!\n  rejectedHint: String!\n  checklistTitle: String!\n  myPairingsTitle: String!\n  pairingMentorRoleLabel: String!\n  pairingMenteeRoleLabel: String!\n  guilds: [HomeRecruitGuild!]!\n  myNewcomer: [HomeRecruitNewcomer!]!\n}\n\n# 招新目录条目: 一个可申请的百业 (已绑定 Discord 服务器且已开启\n# 招新)。myApplicationSection 仅当查看者可对本百业申请 (已登录且\n# 非成员) 时存在; 成员与匿名皆为 null。\ntype HomeRecruitGuild {\n  slug: String!\n  name: String!\n  slogan: String\n  avatarUrl: String\n  myApplicationSection: HomeRecruitApplicationSection\n}\n\n# 查看者在某百业的申请区: application 为其最近一份申请; 从未申请\n# 为 null (申请表单由 section 存在 + application 缺席/被拒驱动)。\ntype HomeRecruitApplicationSection {\n  application: RecruitApplication\n}\n\n# 成员在主页的招新拼装 (按百业一条): checklist 仅成员有值 (被配对\n# 但非成员的条目为 null); myPairings 为本人在该百业的导师配对。\ntype HomeRecruitNewcomer {\n  slug: String!\n  guildName: String!\n  checklist: NewcomerChecklist\n  myPairings: [MentorPairing!]!\n}\n\ntype RecruitPayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n  application: RecruitApplication\n}\n\n# ============ 跨百业网络 (P19 补位市场 / P20 盟友百业) ============\n# 按边收费 (DESIGN.md §9): 供给侧免费 (发布供给 / 处理邀请不问档位),\n# 需求侧 T3 (需求区在未达档时合成 FillDemandLocked, 零需求数据下发;\n# 需求类 mutation 服务端以同一判定复验)。paygate 总闸 OFF 时无人锁定\n# (只建不启用)。市场只撮合不裁决: 接受邀请不落座, 落座是需求方车头\n# 在 seatFillSupplier 里的人工动作 (走既有容量守卫落座)。结盟共享是\n# 读时判定: 解除结盟即刻失效, 无清理写。\n\nunion FillMarketResult = FillMarketPage | FillMarketLocked\n\ntype FillMarketPage {\n  slug: String!\n  guildName: String!\n  supply: FillSupplySection!\n  demand: FillDemandResult!\n  weekdayNames: [String!]!\n  marketTitle: String!\n  marketBody: String!\n  backLabel: String!\n}\n\ntype FillMarketLocked {\n  slug: String!\n  lockedTitle: String!\n  lockedBody: String!\n  backLabel: String!\n}\n\n# 供给区 (免费边): 我的供给 + 我收到的邀请。\ntype FillSupplySection {\n  myOffer: FillOffer\n  myInvites: [FillInvite!]!\n  supplyTitle: String!\n  supplyHint: String!\n  supplyEmptyText: String!\n  schoolLabel: String!\n  windowsLabel: String!\n  noteLabel: String!\n  notePlaceholder: String!\n  publishLabel: String!\n  withdrawLabel: String!\n  inboxTitle: String!\n  inboxEmptyText: String!\n  acceptLabel: String!\n  declineLabel: String!\n}\n\n# 补位供给的公开面: 只含市场必需字段 (流派 / 时段 / 所属百业名 /\n# 自述), 无 Discord ID、无联系方式。\ntype FillOffer {\n  id: ID!\n  displayName: String!\n  school: String!\n  roleLabel: String!\n  note: String!\n  homeTenant: String!\n  homeGuildName: String!\n  homeGuildPattern: String!\n  windows: [AvailabilitySlot!]!\n  statusLabel: String!\n  createdAtText: String!\n}\n\nunion FillDemandResult = FillDemandSection | FillDemandLocked\n\ntype FillDemandLocked {\n  lockedTitle: String!\n  lockedBody: String!\n}\n\n# 需求区 (T3 边): 本百业需求 + 全市场供给浏览。manage 仅当观看者\n# 在本百业有可管理的车 (车头 / 管理员) 时合成, 否则为 null。\ntype FillDemandSection {\n  requests: [FillRequest!]!\n  offers: [FillOffer!]!\n  manage: FillDemandManage\n  demandTitle: String!\n  requestsTitle: String!\n  requestsEmptyText: String!\n  offersTitle: String!\n  offersEmptyText: String!\n  noManageHint: String!\n}\n\ntype FillDemandManage {\n  myGroupings: [FillDemandGrouping!]!\n  createTitle: String!\n  groupingLabel: String!\n  neededRoleLabel: String!\n  neededSchoolLabel: String!\n  noteLabel: String!\n  createLabel: String!\n  roleHealerLabel: String!\n  roleDpsLabel: String!\n}\n\ntype FillDemandGrouping {\n  id: ID!\n  title: String!\n  dungeon: String!\n  startsAtText: String!\n}\n\ntype FillRequest {\n  id: ID!\n  groupingId: ID!\n  groupingTitle: String!\n  dungeon: String!\n  startsAtText: String!\n  neededRole: String!\n  neededRoleLabel: String!\n  neededSchool: String\n  note: String!\n  status: FillRequestStatus!\n  statusLabel: String!\n  createdByName: String!\n  createdAtText: String!\n  # 管理动作对象: 仅本车可管理者 (车头 / 本百业管理员) 有值; 本需求\n  # 的邀请名单只在该对象内下发。mutation 处独立复验。\n  manageActions: FillRequestManageActions\n}\n\nenum FillRequestStatus { OPEN MATCHED CLOSED }\n\ntype FillRequestManageActions {\n  closeLabel: String!\n  seatLabel: String!\n  seatedLabel: String!\n  inviteLabel: String!\n  invitedLabel: String!\n  invites: [FillInvite!]!\n}\n\ntype FillInvite {\n  id: ID!\n  requestId: ID!\n  offerId: ID\n  status: FillInviteStatus!\n  statusLabel: String!\n  fromName: String!\n  toName: String!\n  guildName: String!\n  groupingTitle: String!\n  sourcePattern: String!\n  createdAtText: String!\n  # 落座动作对象: 仅当邀请已接受、观看者可管理该车、且对方尚未\n  # 落座时合成 (需求侧管理视图); 收件箱视图恒为 null。\n  seatAction: FillSeatAction\n}\n\nenum FillInviteStatus { PENDING ACCEPTED DECLINED EXPIRED }\n\ntype FillSeatAction {\n  seatLabel: String!\n}\n\ntype FillOfferPayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n  offer: FillOffer\n}\n\ntype FillRequestPayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n  request: FillRequest\n}\n\ntype FillInvitePayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n  invite: FillInvite\n}\n\ntype NetworkOkPayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n}\n\nunion GuildAlliesResult = GuildAlliesPage | GuildAlliesLocked\n\ntype GuildAlliesPage {\n  slug: String!\n  guildName: String!\n  allies: [AllyGuild!]!\n  # 结盟管理区: 仅本百业管理员有值 (关系列表 + 可邀请目录)。\n  adminSection: AllianceAdminSection\n  sharedGroupings: [AllySharedGrouping!]!\n  alliesTitle: String!\n  alliesBody: String!\n  activeTitle: String!\n  activeEmptyText: String!\n  sharedTitle: String!\n  sharedEmptyText: String!\n  visitorJoinLabel: String!\n  visitorJoinedLabel: String!\n  backLabel: String!\n}\n\ntype GuildAlliesLocked {\n  slug: String!\n  lockedTitle: String!\n  lockedBody: String!\n  backLabel: String!\n}\n\ntype AllyGuild {\n  slug: String!\n  name: String!\n}\n\ntype AllianceAdminSection {\n  relations: [AllianceRelation!]!\n  candidates: [AllyGuild!]!\n  adminTitle: String!\n  inviteLabel: String!\n  inviteHint: String!\n  inviteButtonLabel: String!\n  incomingTitle: String!\n  outgoingTitle: String!\n  acceptLabel: String!\n  rejectLabel: String!\n  endLabel: String!\n}\n\ntype AllianceRelation {\n  id: ID!\n  otherSlug: String!\n  otherName: String!\n  status: AllianceStatus!\n  statusLabel: String!\n  outgoing: Boolean!\n  requestedByName: String!\n  createdAtText: String!\n}\n\nenum AllianceStatus { PENDING ACTIVE }\n\n# 盟友共享活动行: 主办百业的盟友可见车队 + 访客位余量 (读时按当前\n# 结盟状态合成; 非盟友永远查不到这一行)。\ntype AllySharedGrouping {\n  id: ID!\n  hostSlug: String!\n  hostName: String!\n  hostPattern: String!\n  title: String!\n  dungeon: String!\n  startsAtText: String!\n  visitorSlots: Int!\n  visitorLeft: Int!\n  visitorLeftPattern: String!\n  joined: Boolean!\n}\n\ntype AlliancePayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n  alliance: AllianceRelation\n}\n\n# 车队详情的盟友共享控件: 仅可管理本车者有值 (见 GroupingDetailPage)。\ntype AllySharingControl {\n  allyVisible: Boolean!\n  visitorSlots: Int!\n  title: String!\n  hint: String!\n  allyVisibleLabel: String!\n  visitorSlotsLabel: String!\n  saveLabel: String!\n}\n\ntype GuildAdminLotteryMember {\n  discordId: ID!\n  displayName: String!\n}\n\ninput LotteryEntryInput {\n  discordId: ID!\n  weight: Int!\n}\n\ninput CreateLotteryInput {\n  title: String!\n  prize: String\n  source: LotterySource!\n  # source = GROUPING 时必填: 本百业的一辆车; 其已落座参与者按\n  # uniformWeight 定格进名单 (名单成员以报名昵称展示)。\n  sourceEventId: ID\n  uniformWeight: Int\n  # source = MEMBERS 时必填: 手选成员 + 各自权重。\n  entries: [LotteryEntryInput!]\n  winnerCount: Int!\n}\n\n# OG 分享卡强调色选项: 服务端色板 (key + 本地化名 + 色值), 管理员\n# 只能选 key; 色值由后端下发, 前端与 OG worker 都不自备色板。\ntype GuildAdminOgAccentOption {\n  key: String!\n  label: String!\n  hex: String!\n}\n\ntype GuildAdminEvent {\n  id: ID!\n  title: String!\n  type: GroupingType!\n  status: String!\n  origin: String!\n  startsAtUtc: Int\n  startsAtText: String!\n  dungeon: String!\n  maxSlots: Int!\n  meetInfo: String!\n  description: String!\n  signupCount: Int!\n  signups: [GuildAdminSignup!]!\n  results: [GuildAdminRaceResult!]!\n  signupsCsv: String!\n}\n\ntype GuildAdminSignup {\n  id: ID!\n  nickname: String!\n  uid: String!\n  role: String!\n  weapon: String!\n  contact: String!\n  teamName: String!\n  members: String!\n  note: String!\n  createdAt: String!\n}\n\ntype GuildAdminRaceResult {\n  id: ID!\n  teamName: String!\n  members: String!\n  timeMs: Int!\n  timeText: String!\n  proofUrl: String!\n  note: String!\n}\n\n# 流派攻略数据 (BiS / 循环): 与公开流派页同一批 dex 数据; bis 本体是\n# 任意 JSON 文档, 以原文文字列下发/回存 (编辑器即 JSON 文本框, 与原\n# gadmin 的 upsert 语义一致)。\ntype GuildAdminSchoolGuides {\n  schools: [GuildAdminSchoolGuide!]!\n}\n\ntype GuildAdminSchoolGuide {\n  school: String!\n  builds: [GuildAdminSchoolBuild!]!\n  rotationJson: String!\n}\n\ntype GuildAdminSchoolBuild {\n  build: String!\n  attr: String!\n  rate: String!\n  bisJson: String!\n}\n\n# 管理面统计 (出勤/活跃, Premium 第一梯队): 数字全部由后端按既有实体\n# 聚合, 只挂 GuildAdmin (Locked 零统计字段)。周期 = 本周 + 近 4 周逐周\n# 序列, 产品周界 (周一 05:00 北京时间, 半开区间); 两榜为同一 4 周窗口\n# 合计。计数口径: 车按 starts_at_utc 归周, 草稿车与无时间车不计;\n# 总座位 = max_slots 之和, 已坐 = 报名行数; 参与只计带 discord_id 戳\n# 的报名 (代报名的戳是被代报者, 参与记在被代报者名下); 车头榜按\n# creator_discord_id 计开车数, 无戳车跳过。\ntype GuildAdminStats {\n  weeks: [GuildAdminStatsWeek!]!\n  memberLeaders: [GuildAdminStatsMember!]!\n  leaderLeaders: [GuildAdminStatsLeader!]!\n}\n\nunion GuildAdminStatsResult = GuildAdminStats | GuildAdminStatsLocked\n\n# 统计未开通变体: 只带 Premium 未开通文案, 零统计字段。开通面\n# 本体 (价格位 + 开通入口) 在 GuildAdmin.premium 的 Locked 变体上,\n# 两处由同一次权益判定组合, 不会互相矛盾。\ntype GuildAdminStatsLocked {\n  premiumTitle: String!\n  premiumBody: String!\n}\n\nunion GuildAdminPremiumResult = GuildAdminPremiumActive | GuildAdminPremiumLocked\n\n# Active variant: plan name + source (Stripe subscription /\n# platform grant / trial grant) + current period end (manual\n# grants and subscriptions both carry a period; null when none is\n# on file). premiumPastDueText is composed only inside a past-due\n# Stripe grace window (the backend entitlement judgement); it is\n# null at all other times.\ntype GuildAdminPremiumActive {\n  premiumPlanLabel: String!\n  premiumSourceText: String!\n  premiumPeriodEndText: String\n  premiumPastDueText: String\n}\n\n# One tier of the pricing surface: tier name / subtitle / monthly\n# price are all composed and served by the backend (the tier\n# catalog lives in the backend billing service, names go through\n# i18n, prices are formatted from the catalog amounts) — the\n# client hardcodes no tier name or amount. This type appears only\n# on the Locked variant of GuildAdmin.premium: that surface is\n# itself gated by the paygate master switch (switch OFF composes\n# premium as null and serves zero prices), and no feature's\n# tier-locked shell carries this type.\ntype GuildAdminPremiumTierPlan {\n  tier: Int!\n  name: String!\n  subtitle: String!\n  priceLabel: String!\n}\n\n# Locked variant: upsell copy + price slot + checkout entry + the\n# three-tier pricing. Prices render only backend-composed data\n# (premiumPriceLabel is the current plan price read back from\n# Stripe, premiumTierPlans is the backend tier catalog's monthly\n# prices); with Stripe unconfigured, premiumPriceLabel is null\n# and premiumComingSoonText takes its place — the client\n# hardcodes no amount.\ntype GuildAdminPremiumLocked {\n  premiumTitle: String!\n  premiumBody: String!\n  premiumPriceLabel: String\n  premiumComingSoonText: String\n  premiumCheckoutLabel: String!\n  premiumTierPlans: [GuildAdminPremiumTierPlan!]!\n}\n\n# 赛季前检查清单: 条目本体由后端按赛季数据组合 (当前版本副本 /\n# 本百业组队模板 / 流派攻略数据 / 成员名册四项, 全部与既有实体\n# 挂钩, detail 里的计数为生成时刻的真实计数)。勾选状态按\n# (百业, seasonKey) 隔离持久化; 新赛季 seasonKey 变化, 清单\n# 自动回到未勾状态, 无需任何数据迁移。\ntype GuildSeasonChecklist {\n  seasonKey: String!      # 后端赛季身份 \"<版本码>:<赛季码>\"\n  versionLabel: String!   # 当前版本展示串 (settings.game_version)\n  seasonLabel: String!    # 赛季展示串 (后端赛季表组合, 如 \"S5 · Ever Aflame\")\n  title: String!\n  hint: String!           # 已按当前版本/赛季插值完成的说明文案\n  progressTemplate: String!  # \"{done}\" / \"{total}\" 由客户端以计数填充\n  items: [GuildSeasonChecklistItem!]!\n  doneCount: Int!\n  totalCount: Int!\n}\n\ntype GuildSeasonChecklistItem {\n  key: String!            # 稳定条目键 (后端条目表), 勾选 mutation 按键寻址\n  title: String!\n  detail: String!         # 与既有实体的真实计数插值后的说明\n  checked: Boolean!\n  checkedByName: String   # 最近一次勾选/取消的管理员显示名; 从未操作为 null\n}\n\n# 成员名册 (游戏内名字): 与 guild_members (Discord 成员资格) 正交 —\n# 名册条目不产生、不修改任何成员资格。matchedName 是导入时匹配到\n# 的 Discord 名册显示名 (经成员表实时解析, 无匹配为 null)。\ntype GuildRoster {\n  entries: [GuildRosterEntry!]!\n  rosterTitle: String!\n  rosterHint: String!\n  rosterUploadLabel: String!\n  rosterOcrRunningText: String!\n  rosterPreviewTitle: String!\n  rosterConfirmLabel: String!\n  rosterEmptyText: String!\n  rosterDeleteLabel: String!\n  rosterSourceOcrLabel: String!\n  rosterMatchedMemberLabel: String!\n}\n\ntype GuildRosterEntry {\n  id: ID!\n  displayName: String!\n  source: String!         # 数据值 ('ocr'), 非文案\n  matchedName: String     # 匹配到的 Discord 名册显示名; 未匹配为 null\n  createdAt: Int!\n}\n\n# 名册截图 OCR 导入预览: 识别行由后端逐行分类。MATCHED = 已在\n# Discord 名册或既有名册中; NEW = 疑似新名 (可勾选导入);\n# UNRECOGNIZED = 无法识别为名字。预览落库为待确认批次, 管理员\n# 确认前不产生任何名册条目, 更不触碰成员资格。\nenum RosterImportRowStatus {\n  MATCHED\n  NEW\n  UNRECOGNIZED\n}\n\ntype RosterImportRow {\n  id: ID!\n  rawName: String!\n  status: RosterImportRowStatus!\n  statusLabel: String!\n  matchedName: String!    # MATCHED 时的既有显示名; 其余为空串\n  importable: Boolean!    # 数据状态: NEW 且尚未导入 (非权限标志)\n}\n\ntype RosterImportPreview {\n  batchId: ID!\n  rows: [RosterImportRow!]!\n  matchedCount: Int!\n  newCount: Int!\n  unrecognizedCount: Int!\n}\n\ntype RosterImportPayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n  preview: RosterImportPreview\n  importedCount: Int      # confirm 成功时新建的名册条数; 其余为 null\n  message: String         # 成功文案 (后端按结果计数插值); 失败为 null\n}\n\ntype GuildAdminStatsWeek {\n  weekStartUtc: Int!\n  weekLabel: String!\n  isCurrent: Boolean!\n  carsActivity: Int!\n  carsTalent: Int!\n  carsRace: Int!\n  carsTower: Int!\n  carsTotal: Int!\n  completedCount: Int!\n  totalSeats: Int!\n  filledSeats: Int!\n  fillRate: Float!\n  participantCount: Int!\n  participationCount: Int!\n  perCapita: Float!\n}\n\ntype GuildAdminStatsMember {\n  discordId: String!\n  displayName: String!\n  seatCount: Int!\n}\n\ntype GuildAdminStatsLeader {\n  discordId: String!\n  displayName: String!\n  carCount: Int!\n}\n\ntype GuildAdminPayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n  # 头像变更后回带新版本化 URL / 新建实体回带 id (其余变更为 null)\n  avatarUrl: String\n  id: ID\n  # startPremiumCheckout 成功时回带 Stripe Checkout 托管页 URL\n  checkoutUrl: String\n}\n\ninput UpdateGuildProfileInput {\n  name: String\n  announcement: String\n  slogan: String\n  masterName: String\n  logoUrl: String\n  bgImageUrl: String\n}\n\ninput UpdateGuildDiscordInput {\n  # 省略/null = 保持不变; 空串 = 清除; 非空 = 替换 (服务端复验格式)\n  webhook: String\n  discordGuildId: String\n}\n\ninput CreateAdminEventInput {\n  title: String!\n  type: GroupingType!\n  startsAtUtc: Int\n  dungeon: String\n  maxSlots: Int\n  meetInfo: String\n  description: String\n  status: String\n}\n\ninput UpdateAdminEventInput {\n  title: String\n  type: GroupingType\n  startsAtUtc: Int\n  dungeon: String\n  maxSlots: Int\n  meetInfo: String\n  description: String\n  status: String\n}\n\ninput AddEventResultInput {\n  teamName: String!\n  members: String\n  timeText: String!\n  proofUrl: String\n  note: String\n}\n\ninput UpdateSchoolGuideInput {\n  school: String!\n  # build 省略 = 只更新循环; 给出 build = upsert 该 build 的 BiS 行。\n  build: String\n  attr: String\n  rate: String\n  bisJson: String\n  rotationJson: String\n}\n\nextend type Mutation {\n  # 百业管理 (全部在 resolver 内复验服务器管理员结论)\n  updateGuildProfile(slug: String!, input: UpdateGuildProfileInput!): GuildAdminPayload!\n  updateGuildDiscord(slug: String!, input: UpdateGuildDiscordInput!): GuildAdminPayload!\n  updateGuildReminderSettings(slug: String!, offsets: [Int!]!, customText: String): GuildAdminPayload!\n  updateGuildWhiteLabel(slug: String!, hideBranding: Boolean!, ogAccent: String!, ogTitleSuffix: String): GuildAdminPayload!\n  # 开通 Premium: 服务端建 Stripe Checkout Session 并回带托管页\n  # URL。总闸关 / 已开通 / Stripe 未配置时以 errors 目录文案拒绝\n  # (paygateDisabled / premiumActive / premiumComingSoon)。\n  # tier is the target tier (1/2/3, nullable): when given, the\n  # checkout charges that tier's configured Stripe price; a tier\n  # without a configured price is refused as unconfigured\n  # (premiumComingSoon) and never falls back to another tier or\n  # the legacy price; when absent, the legacy single-price path\n  # runs, byte-identical to the pre-tier behavior.\n  startPremiumCheckout(slug: String!, tier: Int): GuildAdminPayload!\n  updateGuildVisibility(slug: String!, devOnly: Boolean!): GuildAdminPayload!\n  # 头像以 base64 文本上传 (GraphQL 无二进制通道); 服务端解码后仍走\n  # 与原直传相同的大小/魔数校验, 错误文案走 errors 目录。\n  setGuildAvatar(slug: String!, dataBase64: String!): GuildAdminPayload!\n  deleteGuildAvatar(slug: String!): GuildAdminPayload!\n  createAdminEvent(slug: String!, input: CreateAdminEventInput!): GuildAdminPayload!\n  updateAdminEvent(slug: String!, eventId: ID!, input: UpdateAdminEventInput!): GuildAdminPayload!\n  deleteAdminEvent(slug: String!, eventId: ID!): GuildAdminPayload!\n  removeEventSignup(slug: String!, signupId: ID!): GuildAdminPayload!\n  addEventResult(slug: String!, eventId: ID!, input: AddEventResultInput!): GuildAdminPayload!\n  deleteEventResult(slug: String!, resultId: ID!): GuildAdminPayload!\n  updateSchoolGuide(slug: String!, input: UpdateSchoolGuideInput!): GuildAdminPayload!\n  # 活动工具 (免费, 不挂权益门; 全部在 resolver 内复验管理结论)\n  createLottery(slug: String!, input: CreateLotteryInput!): GuildAdminPayload!  # 名单创建时定格\n  drawLottery(slug: String!, lotteryId: ID!): GuildAdminPayload!  # 按权重不重复抽取, 结果留痕\n  # 赛季前检查: 勾选/取消一个条目 (键必须是当前赛季清单的真实条目键)\n  setSeasonChecklistItem(slug: String!, itemKey: String!, checked: Boolean!): GuildAdminPayload!\n  # 名册截图 OCR: 客户端识别出的文本行送后端分类, 生成待确认预览\n  # 批次。计量与装备批量 OCR 共用同一日计数 (usage_counters 的\n  # gear_ocr_batches) 与同一限额: 单批张数 + 每日批次, 不新开通道。\n  previewRosterImport(slug: String!, lines: [String!]!, imageCount: Int!): RosterImportPayload!\n  # 确认导入: 仅 rowIds 里 NEW 状态的行落为名册条目; 批次随即关闭。\n  confirmRosterImport(slug: String!, batchId: ID!, rowIds: [ID!]!): RosterImportPayload!\n  deleteGuildRosterEntry(slug: String!, entryId: ID!): GuildAdminPayload!\n  # 招新线 (免费, 不挂权益门; 全部在 resolver 内复验管理结论)\n  updateGuildRecruitOpen(slug: String!, open: Boolean!): GuildAdminPayload!  # 招新开关: 开 = 进主页目录 + 可申请; 关 = 下目录 + 新申请以 recruitClosed 拒绝\n  sendTargetedNudge(slug: String!, eventId: Int!, segmentKind: String!, segmentValue: String): OpsPayload!\n  executeSeasonRollover(slug: String!): OpsPayload!\n  updateContributionRule(slug: String!, actionKey: String!, points: Int!, enabled: Boolean!): OpsPayload!\n  reviewGuildApplication(slug: String!, applicationId: ID!, approve: Boolean!): GuildAdminPayload!  # 通过 = 结案 + 登记名册 (Discord 入服由申请人自行完成, 见 recruit 文案)\n  setGuildMentor(slug: String!, discordId: String!, isMentor: Boolean!): GuildAdminPayload!  # 设/取消导师人选 (不改已有配对)\n  createMentorPairing(slug: String!, mentorDiscordId: String!, menteeDiscordId: String!): GuildAdminPayload!  # 导师须已在人选中; 新人同时至多一段进行中配对\n  endMentorPairing(slug: String!, pairingId: ID!): GuildAdminPayload!  # 结束留痕, 不删行\n}\n\nextend type Mutation {\n  # 入业申请 (F16): 登录的非成员向已绑定且开启招新的百业提交;\n  # 未开启时以 recruitClosed 拒绝; 已有待审申请时以\n  # applicationPending 拒绝 (仓储部分唯一索引同规兜底)。\n  applyToGuild(slug: String!, message: String): RecruitPayload!\n}\n\nextend type Mutation {\n  # —— P19 补位市场 ——\n  # 供给侧 (免费): 本百业成员发布自己的补位供给; 一人同时一份。\n  publishFillOffer(slug: String!, school: String!, windows: [AvailabilitySlotInput!]!, note: String): FillOfferPayload!\n  # 供给侧 (免费): 撤下自己的供给。\n  withdrawFillOffer: NetworkOkPayload!\n  # 需求侧 (T3): 本车车头 / 本百业管理员针对具体车队缺口发布需求。\n  createFillRequest(slug: String!, groupingId: ID!, neededRole: String!, neededSchool: String, note: String): FillRequestPayload!\n  # 需求侧 (T3): 关闭需求 (其余待确认邀请随之失效)。\n  closeFillRequest(slug: String!, requestId: ID!): NetworkOkPayload!\n  # 需求侧 (T3): 向一份供给发出邀请。\n  inviteFillSupplier(slug: String!, requestId: ID!, offerId: ID!): FillInvitePayload!\n  # 供给侧 (免费): 补位人确认 / 婉拒邀请。接受只撮合, 不落座。\n  respondFillInvite(inviteId: ID!, accept: Boolean!): FillInvitePayload!\n  # 需求侧 (T3): 人工落座 — 车头把已接受邀请的补位人落进车队\n  # (既有容量守卫落座动作; 永不自动触发)。\n  seatFillSupplier(slug: String!, inviteId: ID!): NetworkOkPayload!\n  # —— P20 盟友百业 ——\n  # 本百业管理员向另一百业发起结盟邀请。\n  inviteAlliance(slug: String!, targetSlug: String!): AlliancePayload!\n  # 被邀请方百业管理员接受 / 拒绝结盟。\n  respondAlliance(slug: String!, allianceId: ID!, accept: Boolean!): AlliancePayload!\n  # 任一方管理员单方解除结盟 (共享读时即刻失效)。\n  endAlliance(slug: String!, allianceId: ID!): AlliancePayload!\n  # 车头 / 本百业管理员设置本车的盟友共享 (可见 + 访客名额)。\n  setGroupingAllySharing(slug: String!, groupingId: ID!, allyVisible: Boolean!, visitorSlots: Int!): NetworkOkPayload!\n  # 盟友成员报名访客位 (slug = 报名者自己的百业; 服务端复验当前\n  # 结盟状态 / 共享开关 / 访客余量, 走既有容量守卫)。\n  joinAllyGrouping(slug: String!, groupingId: ID!, weapon: String!): NetworkOkPayload!\n}\n\n# ============ OG 卡面数据通道 (公开, 只读) ============\n# OG worker 专用窄通道, 替代原 REST 三读 (/api/tenants、本周车表、\n# 车详情)。只暴露卡面本来就公开的字段: 百业名/标语对匿名公开是产品\n# 裁决 (2026-10-25); 车卡字段与原 REST 详情的卡面子集逐一对应, 绝不\n# 含成员昵称等报名明细。dev_only 百业从非 dev 来源看不存在 (同全站规矩)。\n\ntype OgGuildCard {\n  exists: Boolean!\n  name: String!\n  slogan: String!\n  # 本周 (周一 05:00 北京边界) 招募中的双十车数, 口径与原 REST 周表\n  # 计数完全一致 (activity 且 status 不在 draft/completed)。\n  weekActivityCount(fromUtc: Int!, toUtc: Int!): Int!\n  # 白标分享卡定制: 已解析的强调色色值 (空 = 未定制, OG worker 用\n  # 默认模板渲染, 与定制前逐字节一致) 与标题后缀 (空 = 无后缀)。\n  # 只下发色板校验后的值, 永不下发管理员原始输入。\n  ogAccentColor: String!\n  ogTitleSuffix: String!\n}\n\ntype OgCarCard {\n  title: String!\n  type: String!\n  startsAtUtc: Int\n  startsAtText: String!\n  dungeonName: String!\n  occupiedCount: Int!\n  maxSlots: Int!\n  status: String!\n}\n\n# 方案分享卡: 只取卡面字段 (方案名/流派标签/毕业度快照), 永不下发\n# 所有者身份; 码不存在/已撤销/方案已删 -> null。\ntype OgBuildCard {\n  name: String!\n  buildLabel: String!\n  snapTotal: Float!\n  snapA: Float!\n  snapB: Float!\n  snapD: Float!\n}\n\nextend type Query {\n  ogGuildCard(slug: String!): OgGuildCard!\n  # OG 预热枚举: 全部百业 slug (dev_only 仅 dev 来源可见, 与旧 /api/tenants 同门控)\n  ogGuildSlugs: [String!]!\n  ogCarCard(slug: String!, id: ID!): OgCarCard\n  ogBuildCard(code: String!): OgBuildCard\n}\n\n# ============ 配装台数据/计算 (gear-planner 移植, src/gearplanner.js) ============\n# 口径与 calcGraduation 不同: 毕业度 = (40% 条数 + 24% 数值 + 20% 定音) / 84\n# (关定音 / 64); 单件评分 = round((60 × 核心凑齐 + 40 × 数值加权) × 条数因子)。\n\ntype GearBuild {\n  idx: Int!\n  cat: String!\n  school: String!\n  set: String!\n  bow: String!\n  bowKind: String!\n  bowLabel: String!\n  note: String\n  recipe: String!\n  sectName: String!\n  totalBars: Int!\n  targets: [GearTarget!]!\n}\n\ntype GearTarget {\n  cls: String!\n  label: String!\n  n: Int!\n  flex: [String!]\n}\n\ntype GearAffixRow {\n  key: String!\n  label: String!\n  short: String!\n  max: Float!\n  cy: Float!\n  unit: String!\n  sys: String\n  size: String\n  cyPct: Float!\n  recipeNames: [String!]!\n}\n\ntype GearSlotRow {\n  slot: String!\n  lines: [String!]!\n}\n\ntype GearBaseField {\n  key: String!\n  label: String!\n  preset: Float!\n}\n\ntype GearXinfaRow {\n  name: String!\n  xiao: Float\n  da: Float\n  acc: Float\n  crit: Float\n  int: Float\n  dcrit: Float\n  dint: Float\n  dmg: Float\n  pierce: Float\n  critDmg: Float\n  intDmg: Float\n  shuSys: String\n  shuXiao: Float\n  shuDa: Float\n  sysPierceSys: String\n  sysPierceVal: Float\n  shuBonusSys: String\n  shuBonusVal: Float\n}\n\ntype GearTalentRow {\n  name: String!\n  text: String!\n  xiao: Float!\n  da: Float!\n  acc: Float!\n  crit: Float!\n  int: Float!\n}\n\ntype GearDingyinRow {\n  school: String!\n  name: String\n  wuxue: String\n  verified: Boolean!\n  category: String\n}\n\ntype GearNameMax {\n  name: String!\n  max: Float!\n}\n\ntype GearBowRow {\n  kind: String!\n  label: String!\n  acc: Float!\n  crit: Float!\n  int: Float!\n}\n\ntype GearNameKey {\n  name: String!\n  key: String!\n}\n\ntype GearNameCls {\n  name: String!\n  cls: String!\n}\n\ntype GearDemoItem {\n  slot: String!\n  name: String!\n  keys: [String!]!\n  dingyinName: String!\n  dingyinVal: Float!\n}\n\ntype GearDimRow {\n  name: String!\n  conv: String!\n  full: String!\n}\n\ninput GearLineInput {\n  key: String!\n  val: Float!\n}\n\ninput GearDingyinInput {\n  name: String!\n  val: Float!\n}\n\ninput GearItemInput {\n  id: Int!\n  slot: String!\n  name: String\n  lines: [GearLineInput!]!\n  dingyin: GearDingyinInput\n  schools: [String!]\n}\n\ninput GearBaseValueInput {\n  key: String!\n  val: Float\n}\n\ninput GearSimInput {\n  id: Int!\n  tier: String!\n}\n\ninput GearLoadoutEntryInput {\n  slot: String!\n  gearId: Int!\n}\n\ninput GearPlanInput {\n  targetIdx: Int!\n  baseValues: [GearBaseValueInput!]\n  xinfa: [String!]\n  res: Float\n  extraAcc: Float\n  extraCrit: Float\n  extraInt: Float\n  bowKind: String\n  gradDingyinOn: Boolean\n  sim: [GearSimInput!]\n  lib: [GearItemInput!]!\n  loadout: [GearLoadoutEntryInput!]\n}\n\ntype GearKV {\n  key: String!\n  val: Float!\n}\n\ntype GearOtherShu {\n  key: String!\n  label: String!\n  val: Float!\n  count: Int!\n}\n\ntype GearInvalidLine {\n  gearId: Int!\n  key: String!\n  val: Float!\n}\n\ntype GearPanel {\n  whiteAcc: Float!\n  whiteCrit: Float!\n  whiteInt: Float!\n  yAcc: Float!\n  yCrit: Float!\n  yInt: Float!\n  finalCrit: Float!\n  dawai: Float!\n  xiaowai: Float!\n  dashu: Float!\n  xiaoshu: Float!\n  hp: Float!\n  def: Float!\n  ti: Float!\n  jin: Float!\n  yu: Float!\n  min: Float!\n  shi: Float!\n  talentCrit: Float!\n  talentXiaowai: Float!\n  talentInt: Float!\n  talentDawai: Float!\n  talentIntStat: String!\n  talentDawaiStat: String!\n  equippedIds: [Int!]!\n  sums: [GearKV!]!\n  classCounts: [GearKV!]!\n  otherShu: [GearOtherShu!]!\n  dingyinTotals: [GearKV!]!\n  invalidLines: [GearInvalidLine!]!\n}\n\ntype GearGradRow {\n  cls: String!\n  label: String!\n  n: Int!\n  cur: Int!\n  flex: Boolean!\n}\n\ntype GearLowLine {\n  gearId: Int!\n  key: String!\n  val: Float!\n  score: Float!\n}\n\ntype GearDingyinScoreRow {\n  slot: String!\n  name: String!\n  val: Float\n  max: Float\n  correct: Boolean!\n  score: Float!\n  has: Boolean!\n}\n\ntype GearGrad {\n  total: Float!\n  a: Float!\n  b: Float!\n  d: Float!\n  got: Int!\n  totalBars: Int!\n  rows: [GearGradRow!]!\n  lowLines: [GearLowLine!]!\n  dingyinRows: [GearDingyinScoreRow!]!\n}\n\ntype GearSuggestion {\n  kind: String!\n  slot: String!\n  gearId: Int\n  name: String\n  lineIdx: Int\n  fromCls: String\n  toCls: String\n  toKey: String\n  gain: Float!\n  score: Float!\n}\n\ntype GearSuggestions {\n  cur: Float!\n  final: Float!\n  list: [GearSuggestion!]!\n}\n\ntype GearExtraClass {\n  cls: String!\n  label: String!\n  count: Int!\n}\n\ntype GearEval {\n  id: Int!\n  score: Int!\n  quality: Float!\n  hits: Int!\n  verdict: String!\n}\n\ntype GearPlanResult {\n  panel: GearPanel!\n  grad: GearGrad!\n  realPanel: GearPanel!\n  realGrad: GearGrad!\n  loanGrad: GearGrad!\n  suggestions: GearSuggestions!\n  extraClasses: [GearExtraClass!]!\n  gearEvals: [GearEval!]!\n  baseNotes: [String!]!\n  xinfaPicked: [String!]!\n  xinfaDuplicates: [String!]!\n}\n\ntype GearAutoResult {\n  loadout: [GearLoadoutEntry!]!\n  fallbackUsed: Boolean!\n}\n\ntype GearLoadoutEntry {\n  slot: String!\n  gearId: Int!\n}\n\ntype GearParsedItem {\n  slot: String!\n  name: String!\n  lines: [GearLine!]!\n  dingyin: GearDingyin\n}\n\ntype GearLine {\n  key: String!\n  val: Float!\n}\n\ntype GearDingyin {\n  name: String!\n  val: Float!\n}\n\ntype GearParseResult {\n  mode: String!\n  unknown: Int!\n  gears: [GearParsedItem!]!\n  fullExportJson: String\n}\n\ninput GearQuickInput {\n  whiteAcc: Float!\n  whiteCrit: Float!\n  whiteInt: Float!\n  res: Float\n}\n\ntype GearRateStatus {\n  yellow: Float!\n  capped: Boolean!\n  over: Float!\n  lack: Float!\n  needWhite: Float!\n  bars: Int!\n}\n\ntype GearQuickResult {\n  res: Float!\n  acc: GearRateStatus!\n  crit: GearRateStatus!\n  int: GearRateStatus!\n}\n\nextend type Mutation {\n  # 配装台整表计算 (面板/毕业度/满值模拟/建议/单件评估)\n  gearPlan(input: GearPlanInput!): GearPlanResult!\n  # 一键最优组合\n  gearAutoCombine(targetIdx: Int!, lib: [GearItemInput!]!): GearAutoResult!\n  # 粘贴代码解析 (与原站解析器同口径; 未知词条跳过并计数)\n  gearParsePaste(text: String!): GearParseResult!\n  # 三率速算\n  gearQuickCalc(input: GearQuickInput!): GearQuickResult!\n}\n\n# ============ 配装台装备库 (D1 按账号存储; 匿名无库, 查询只回自己的) ============\n\ntype GearItem {\n  id: Int!\n  slot: String!\n  name: String!\n  lines: [GearLine!]!\n  dingyin: GearDingyin\n  schools: [String!]!\n  warnings: [String!]!\n}\n\ntype GearBaseValue {\n  key: String!\n  val: Float\n}\n\ntype GearSavedBuild {\n  id: Int!\n  name: String!\n  targetIdx: Int!\n  buildLabel: String!\n  school: String!\n  loadout: [GearLoadoutEntry!]!\n  baseValues: [GearBaseValue!]!\n  xinfa: [String!]!\n  res: Float!\n  extraAcc: Float!\n  extraCrit: Float!\n  extraInt: Float!\n  bowKind: String!\n  gradDingyinOn: Boolean!\n  snapTotal: Float!\n  snapA: Float!\n  snapB: Float!\n  snapD: Float!\n  snapLoan: Float!\n  snapYAcc: Float!\n  snapYCrit: Float!\n  snapYInt: Float!\n  snapDawai: Float!\n  snapXiaowai: Float!\n  createdAt: Int!\n  # 公开分享链 (仅所有者自己的方案列表里组合下发): 未分享为 null,\n  # 已分享为 /b/<code> 完整地址。一条方案同时至多一条有效链。\n  shareUrl: String\n}\n\nextend type Query {\n  myGearItems: [GearItem!]!\n  myGearBuilds: [GearSavedBuild!]!\n}\n\n# ============ 公开方案分享页 (/b/:code, 匿名只读) ============\n# 参观面: 只呈现被分享的那一套方案 (名/流派/心法/装备卡/毕业度\n# 摘要), 摸不到所有者的其他方案/装备库/任何身份字段。码不存在、\n# 已撤销或方案已删时 exists=false, 数据字段回空。\ntype SharedBuildItem {\n  slot: String!\n  name: String!\n  lines: [GearLine!]!\n  dingyin: GearDingyin\n  warnings: [String!]!\n}\n\ntype SharedBuildPage {\n  exists: Boolean!\n  name: String\n  buildLabel: String\n  school: String\n  items: [SharedBuildItem!]!\n  xinfa: [String!]!\n  bowKind: String!\n  snapTotal: Float!\n  snapA: Float!\n  snapB: Float!\n  snapD: Float!\n  snapLoan: Float!\n  snapYAcc: Float!\n  snapYCrit: Float!\n  snapYInt: Float!\n  buildShareKicker: String!\n  buildShareLoginLabel: String!\n  buildShareNotFoundTitle: String!\n  buildShareNotFoundBody: String!\n  buildShareXinfaLabel: String!\n}\n\nextend type Query {\n  sharedBuild(code: String!): SharedBuildPage!\n}\n\ntype GearBuildSharePayload {\n  ok: Boolean!\n  shareUrl: String\n  error: String\n  errorCode: String\n}\n\ninput GearItemCreateInput {\n  slot: String!\n  name: String\n  lines: [GearLineInput!]!\n  dingyin: GearDingyinInput\n  schools: [String!]\n}\n\ntype GearItemPayload {\n  ok: Boolean!\n  item: GearItem\n  error: String\n  errorCode: String\n}\n\ntype GearOkPayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n}\n\ntype GearImportResult {\n  ok: Boolean!\n  items: [GearItem!]!\n  autoSelect: [GearLoadoutEntry!]!\n  error: String\n  errorCode: String\n}\n\ninput GearBuildSaveInput {\n  name: String!\n  targetIdx: Int!\n  loadout: [GearLoadoutEntryInput!]\n  baseValues: [GearBaseValueInput!]\n  xinfa: [String!]\n  res: Float\n  extraAcc: Float\n  extraCrit: Float\n  extraInt: Float\n  bowKind: String\n  gradDingyinOn: Boolean\n}\n\ntype GearBuildPayload {\n  ok: Boolean!\n  build: GearSavedBuild\n  error: String\n  errorCode: String\n}\n\nextend type Mutation {\n  addGearItem(input: GearItemCreateInput!): GearItemPayload!\n  updateGearItem(id: Int!, input: GearItemCreateInput!): GearItemPayload!\n  deleteGearItem(id: Int!): GearOkPayload!\n  # 批量导入 (文件导入/粘贴导入/OCR 批量共用); autoSelect 按传入的当前搭配\n  # 复刻原站「导入后自动选入空位」: 武器先主后副, 其余取空位。\n  # source='ocr' 时为批量截图识别导入, imageCount 为本批截图张数, 服务端\n  # 按限额服务计量 (单批张数 + 每日批次); 所有导入都受装备库件数上限\n  # 约束, 超限整批拒绝、不截断。\n  importGearItems(items: [GearItemCreateInput!]!, loadout: [GearLoadoutEntryInput!], source: String, imageCount: Int): GearImportResult!\n  saveGearBuild(input: GearBuildSaveInput!): GearBuildPayload!\n  deleteGearBuild(id: Int!): GearOkPayload!\n  # 方案公开分享: 生成 (或复用已有) 分享链 / 取消分享 (旧链立即失效)\n  shareGearBuild(id: Int!): GearBuildSharePayload!\n  revokeGearBuildShare(id: Int!): GearOkPayload!\n}\n\n# ============ Premium ops engine (P8/P11/P12/P14, T2) ============\n# The GuildAdmin.ops verdict is the type itself: below T2 it resolves\n# only GuildAdminOpsLocked (lock copy only; the engines are never\n# computed or shipped); at tier it resolves the full GuildAdminOps.\n\nunion GuildAdminOpsResult = GuildAdminOps | GuildAdminOpsLocked\n\ntype GuildAdminOpsLocked {\n  premiumTitle: String!\n  premiumBody: String!\n}\n\ntype GuildAdminOps {\n  title: String!\n  hint: String!\n  nudgeTitle: String!\n  nudgeHint: String!\n  nudgeEventLabel: String!\n  nudgeSegmentLabel: String!\n  segmentAllText: String!\n  segmentSchoolText: String!\n  segmentRoleText: String!\n  segmentLapsedText: String!\n  nudgeSegmentValueLabel: String!\n  nudgePreviewLabel: String!\n  nudgeSendLabel: String!\n  nudgeDailyRemainingText: String\n  nudgeEvents: [OpsNudgeEvent!]!\n  churnTitle: String!\n  churnHint: String!\n  churnEmptyText: String!\n  churnRisks: [OpsChurnRisk!]!\n  rolloverTitle: String!\n  rolloverHint: String!\n  rolloverExecuteLabel: String!\n  rollover: OpsRollover!\n  pointsTitle: String!\n  pointsHint: String!\n  pointsBoardEmptyText: String!\n  pointsTotalLabel: String!\n  pointsEntriesLabel: String!\n  pointsSaveLabel: String!\n  contributionRules: [OpsContributionRule!]!\n  contributionBoard: [OpsContributionBoardEntry!]!\n}\n\ntype OpsNudgeEvent {\n  id: ID!\n  title: String!\n  startsAtText: String!\n  signupCount: Int!\n  maxSlots: Int!\n}\n\ntype OpsChurnRisk {\n  discordId: String!\n  displayName: String!\n  baselineCount: Int!\n  recentCount: Int!\n  missStreak: Int!\n  evidenceText: String!\n  lastText: String!\n}\n\ntype OpsRollover {\n  seasonLabel: String!\n  targetSeasonKey: String!\n  pendingCount: Int!\n  totalCount: Int!\n  copiedCount: Int!\n  pendingNames: [String!]!\n  previewText: String!\n  seasonText: String!\n  gearNoteText: String!\n  thresholdNoteText: String!\n  lastText: String\n}\n\ntype OpsContributionRule {\n  actionKey: String!\n  actionLabel: String!\n  points: Int!\n  enabled: Boolean!\n}\n\ntype OpsContributionBoardEntry {\n  discordId: String!\n  displayName: String!\n  totalPoints: Int!\n  entryCount: Int!\n}\n\nunion TargetedNudgePreviewResult = TargetedNudgePreview | GuildAdminOpsLocked\n\ntype TargetedNudgePreview {\n  candidateCount: Int!\n  countText: String!\n  emptyText: String\n  dailyRemaining: Int!\n  candidates: [OpsNudgeCandidate!]!\n}\n\ntype OpsNudgeCandidate {\n  discordId: String!\n  displayName: String!\n  knownWeapon: String!\n  knownRole: String!\n  lastText: String!\n}\n\ntype OpsPayload {\n  ok: Boolean!\n  error: String\n  errorCode: String\n  recipientCount: Int\n  copiedCount: Int\n}\n\n# My contribution points (P14 free record layer: own balance and\n# ledger, gated on membership only, with no tier verdict).\nunion MyContributionResult = MyContribution | MyContributionLocked\n\ntype MyContribution {\n  title: String!\n  totalPoints: Int!\n  totalText: String!\n  entries: [MyContributionEntry!]!\n}\n\ntype MyContributionLocked {\n  slug: String!\n}\n\ntype MyContributionEntry {\n  actionKey: String!\n  actionLabel: String!\n  points: Int!\n  createdAtText: String!\n}\n";
